"""Cuaderno del estudiante, 2.º medio Lengua y Literatura, OA 04 (poesía, soneto, símbolos y voz) y OA 05 (drama, atmósfera y puesta en escena).

Todos los poemas, escenas y textos son originales e inventados («de ejemplo»); cada ejercicio trae escritos los textos que necesita.
Nota: los títulos de las clases del repositorio ordenan el OA en pasos genéricos (entrar al texto, evidencias, recursos,
contraste, contexto, lectura propia, revisión); este cuaderno los sigue y reparte entre ellos los contenidos del OA oficial.
Ayudantes copiados de le_m2_a: `E`, `L`, `task`, `MAT`.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA4 = "LE2M OA 04"
OA5 = "LE2M OA 05"
E = ex

MAT = "Este cuaderno, lápiz y los textos y datos escritos en cada ejercicio. No necesitas libros especiales ni internet."


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend, materials=MAT):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


# ------------------------------------------------------------------ OA 04 · clase 1
P1A = "«Mi abuelo remienda redes junto al muelle, / con dedos que conocen cada nudo. / Yo lo miro y no sé cómo se aprende / a sostener el mar con tanta calma.»"
P1B = "«¡Qué suerte la mía! El bus pasó antes de que llegara, / la lluvia me esperaba puntual en la esquina, / y mi paraguas, tan leal, se quedó en casa. / Qué generoso día para quien ama mojarse.»"

L(OA4, 1,
  "Aprenderé a entrar a un poema con un propósito: identificar al hablante lírico, el tema y la actitud del hablante hacia ese tema.",
  ["Reconozco versos y estrofas.", "Distingo de qué trata un texto de lo que opino sobre él."],
  ["Un poema se lee con un propósito, es decir, con una pregunta que guía la lectura. Una pregunta útil para empezar es: ¿quién habla y cómo se siente frente a lo que dice? Quien habla en el poema es el hablante lírico, una voz creada por el autor. Puede decir «yo», pero no es necesariamente el autor: puede ser una niña, un anciano o incluso un objeto. Por eso no conviene afirmar qué vivió el autor a partir de lo que dice el hablante.",
   "El tema es aquello de lo que trata el poema (la espera, la infancia, un oficio, la lluvia). La actitud del hablante es la postura o el sentimiento que muestra hacia ese tema: admiración, nostalgia, esperanza, rabia, indiferencia o ironía. La ironía consiste en decir lo contrario de lo que se piensa para mostrar molestia o crítica. Dos poemas pueden tratar el mismo tema y tener actitudes muy distintas.",
   "La actitud no se adivina: se justifica con pistas del texto. Algunas pistas son las palabras valorativas (las que aprecian o juzgan, como «calma» o «vacía»), los verbos, las exclamaciones y preguntas, y lo que el hablante elige mirar. Para registrarla, escribe una oración con tres partes: el tema, la actitud y la pista que la prueba. Por ejemplo: «el hablante admira el oficio de su abuelo, pues dice que sostiene el mar con tanta calma»."],
  [("hablante lírico", "voz que habla en el poema, creada por el autor"), ("tema", "aquello de lo que trata el poema"), ("actitud del hablante", "postura o sentimiento del hablante hacia el tema"), ("ironía", "decir lo contrario de lo que se piensa para mostrar molestia o crítica"), ("pista", "palabra o verso del texto que prueba una lectura")],
  [("Hallar la actitud con una pista", f"Poema de ejemplo: {P1A} ¿Cuál es el tema y qué actitud tiene el hablante?",
    ["Quien habla dice «yo» y mira a su abuelo: el hablante es una persona que observa.", "El tema es el oficio y el saber del abuelo.", "La pista «no sé cómo se aprende a sostener el mar con tanta calma» muestra admiración."],
    "Tema: el oficio del abuelo. Actitud: admiración, probada por «tanta calma»"),
   ("Reconocer la ironía", f"Poema de ejemplo: {P1B} ¿Qué actitud muestra el hablante?",
    ["Leo lo que dice: «qué suerte», «tan leal», «generoso día».", "Pero lo que cuenta es un día de mala suerte: perdió el bus y se mojó.", "Dice lo contrario de lo que siente: hay ironía y molestia."],
    "Ironía: aparenta agradecer, pero expresa molestia")],
  [("Decir que el hablante es siempre el autor y contar su vida a partir del poema.", "El hablante es una voz creada; el autor pudo imaginar esa situación.", "Habla del «hablante» y apóyate en lo que dice el texto, no en la biografía."),
   ("Escribir una actitud sin ninguna pista: «el hablante está triste».", "Una actitud sin evidencia es solo una opinión.", "Agrega la palabra o el verso que lo prueba.")],
  ([E("¿Quién habla en un poema? A) el hablante lírico, una voz creada por el autor B) el autor, que cuenta siempre lo que él mismo vivió y sintió", "A) el hablante lírico, una voz creada por el autor", "El hablante puede ser una persona o un objeto distinto del autor; por eso se lo nombra aparte."),
    E("En un poema, ¿qué es la actitud del hablante? A) la postura o el sentimiento que muestra hacia el tema B) el tema del poema, es decir, aquello de lo que habla el hablante", "A) la postura o el sentimiento que muestra hacia el tema", "La actitud responde a cómo se siente frente al tema; el tema es aquello de lo que se habla."),
    E("Versos de ejemplo: «Ya nadie sube a la loma donde jugábamos; el pasto cubrió el camino y yo lo recuerdo todo.» ¿Qué actitud domina? A) nostalgia B) rabia C) esperanza", "A) nostalgia", "Recuerda con pena un lugar de juego abandonado; no hay reproche ni espera de que algo mejore.")],
   [E("Poema de ejemplo: «Aunque el invierno dura, / la semilla en la tierra / ya sabe su trabajo / y empuja sin que nadie la vea.» ¿Qué actitud muestra el hablante? A) confianza esperanzada en que la semilla crecerá B) indiferencia, porque la semilla crece sola sin que nadie la cuide C) ironía: dice que la semilla trabaja, pero piensa que no crecerá", "A) confianza esperanzada en que la semilla crecerá", "Dice que la semilla «ya sabe su trabajo» y «empuja»: confía en el crecimiento aunque el invierno dure."),
    E("Versos de ejemplo: «¡Otra vez cerraron la plaza! ¡Otra vez sin un lugar para el barrio!» ¿Qué pistas muestran la molestia del hablante? A) las exclamaciones y la repetición de «otra vez», que insiste en el problema B) la mención de la plaza y del barrio, que son los lugares de los que se habla", "A) las exclamaciones y la repetición de «otra vez», que insiste en el problema", "Las exclamaciones y la insistencia revelan emoción; nombrar un lugar no muestra actitud."),
    E("Una autora de cuarenta años escribe un poema cuyo hablante es una niña que espera su primer día de clases. ¿Quién habla en el poema? A) la niña, hablante lírico creado por la autora B) la autora de cuarenta años, que cuenta cómo es su vida actual", "A) la niña, hablante lírico creado por la autora", "El hablante es la voz que el texto construye, aunque la autora sea adulta.")],
   [E("Poema de ejemplo: «Dejé mi bicicleta junto al portón / y el candado se llenó de moho; / en el patio, las sillas sin nadie / aún guardan el calor de las voces.» ¿Qué actitud muestra el hablante? A) nostalgia por un tiempo en que había gente B) alegría por la tranquilidad de estar solo C) burla hacia quienes se fueron", "A) nostalgia por un tiempo en que había gente", "«Las sillas sin nadie» que «aún guardan el calor de las voces» muestran que extraña a quienes estaban."),
    E("Poema X: «Llegó la lluvia: bendita sea, lava el polvo de la tarde.» Poema Y: «Llegó la lluvia: otra tarde perdida entre goteras.» ¿Qué relación hay entre ambos? A) mismo tema (la lluvia) y actitudes distintas B) mismo tema (la lluvia) y la misma actitud de agradecimiento C) temas distintos (polvo y goteras) y la misma actitud de queja", "A) mismo tema (la lluvia) y actitudes distintas", "Los dos tratan de la lluvia; uno la agradece («bendita sea») y el otro se queja («tarde perdida»)."),
    E("Verso de ejemplo: «Gracias, vecino, por tu fiesta de anoche: dormí tres horas, qué considerado eres.» ¿Qué actitud hay? A) ironía: agradece lo que en realidad le molestó B) gratitud sincera: agradece que el vecino lo haya acompañado", "A) ironía: agradece lo que en realidad le molestó", "Elogia («qué considerado») algo que le quitó el sueño: dice lo contrario de lo que siente.")],
   [E("Un estudiante concluye: «En este poema el hablante llora la muerte de su madre; por lo tanto, la autora perdió a su madre». ¿Qué problema tiene esa conclusión? A) confunde al hablante lírico con la autora, que pudo crear esa voz B) ninguno, porque el hablante siempre cuenta la vida real de la autora", "A) confunde al hablante lírico con la autora, que pudo crear esa voz", "El hablante es una voz construida; no se puede deducir de él la biografía del autor."),
    E("Poema de ejemplo: «Sobre la mesa sigue la taza de mi madre. / Nadie la mueve: la cuidamos como a ella. / La miro cada mañana, / y el día se vuelve más claro.» Ana dice que el hablante siente cariño y respeto. Beto dice que siente rabia contra su familia por no lavar la taza. ¿Quién se apoya mejor en el texto? A) Ana, por «la cuidamos como a ella» y «el día se vuelve más claro» B) Beto, por «nadie la mueve» y por «sobre la mesa sigue la taza»", "A) Ana, por «la cuidamos como a ella» y «el día se vuelve más claro»", "Esos versos muestran cuidado y consuelo; «nadie la mueve» es una decisión de conservarla, no un reproche.")],
   [E("Poema de ejemplo: «Me dijeron que crecer era fácil: / bastaba con cerrar la puerta. / Cerré la puerta, y el pasillo / seguía lleno de preguntas. / No me quejo: / aprendo a vivir con la luz prendida.» ¿Qué actitud domina al final? A) aceptación serena ante una dificultad B) rabia contra quienes le mintieron C) indiferencia total", "A) aceptación serena ante una dificultad", "«No me quejo» y «aprendo a vivir con la luz prendida» muestran que acepta la dificultad sin enojarse."),
    E("Poema de ejemplo: «Al principio miré el campo vacío / con un miedo que me apretaba el pecho. // Hoy lo cruzo despacio, descalzo, / y cada surco me dice: “bienvenido”.» ¿Cómo cambia la actitud entre las dos estrofas? A) del miedo a la confianza B) de la alegría a la tristeza C) de la rabia a la indiferencia", "A) del miedo a la confianza", "La primera estrofa habla de miedo; la segunda, de cruzar despacio y sentirse recibido.")]),
   [E("Para el aniversario del liceo debes elegir un poema que transmita orgullo por el barrio. Poema 1: «En mi calle hay un muro con grietas / que nadie sabe arreglar; / pero cada mañana lo pinta el sol / de un color que no se compra.» Poema 2: «Esta calle me aburre: / siempre los mismos muros, / siempre los mismos ruidos, / siempre yo.» ¿Cuál eliges? A) el 1, porque su hablante aprecia su calle pese a las grietas B) el 2, porque nombra los muros y los ruidos que hay en el barrio", "A) el 1, porque su hablante aprecia su calle pese a las grietas", "Su actitud es de aprecio («un color que no se compra»); el hablante del poema 2 muestra aburrimiento.")],
  [E("¿Qué es el tema de un poema? A) aquello de lo que trata B) lo que siente el hablante hacia aquello de lo que trata", "A) aquello de lo que trata", "Lo que el hablante siente hacia el tema es la actitud; el tema es el asunto."),
   E("¿Qué es la ironía en un poema? A) decir lo contrario de lo que se piensa para mostrar molestia o crítica B) repetir una misma palabra o estructura al comienzo de varios versos", "A) decir lo contrario de lo que se piensa para mostrar molestia o crítica", "Así se definió en la clase: el hablante aparenta una cosa y expresa otra."),
   E("Para justificar la actitud del hablante, ¿qué se necesita? A) pistas del texto, como palabras valorativas o exclamaciones B) saber qué vivió el autor y en qué año escribió el poema", "A) pistas del texto, como palabras valorativas o exclamaciones", "La actitud se prueba con el poema; la vida del autor no es una evidencia del texto.")],
  ("Lee estos dos poemas de ejemplo. Poema X: «Cada vez que llueve en el puerto / mi madre cuenta las goteras / y sonríe: sabe que el techo / aguanta un poco más que el miedo.» Poema Y: «¿Otra vez los gritos del vecino? / ¿Otra vez la radio a todo volumen? / Qué barrio tan tranquilo, qué suerte: / aquí nadie sabe lo que es dormir.» Escribe tres oraciones por cada poema: 1) quién habla y de qué trata, 2) la actitud del hablante, 3) la pista que la prueba.",
   "Poema X: habla una persona que observa a su madre durante la lluvia; trata de cómo ella enfrenta las goteras. La actitud es de cariño y admiración por su serenidad. La pista es que ella «sonríe: sabe que el techo aguanta un poco más que el miedo». Poema Y: habla alguien molesto por el ruido del vecindario. La actitud es irónica. La pista es que llama «tranquilo» y «suerte» a un barrio donde «nadie sabe lo que es dormir».",
   ["distingue hablante y tema", "nombra una actitud adecuada para cada poema", "cita una pista textual por poema"], ["seis oraciones en el cuaderno"], ["confundir tema y actitud", "no detectar la ironía del poema Y", "dar la actitud sin pista"],
   "Subraya en cada poema la pista que citaste y comprueba que de verdad pruebe la actitud."),
  "Mira un poema o una canción que haya en tu casa y anota quién habla, de qué trata y qué actitud muestra, con una pista.",
  "Escribe un poema de cuatro versos sobre el mismo tema con dos actitudes distintas, uno con admiración y otro con ironía.")

# ------------------------------------------------------------------ OA 04 · clase 2
PC = "«El puente de madera cruje, / pero sostiene mis pasos. / Atrás quedó la casa vieja; / delante, una orilla sin nombre.»"
PK = "«Dejé la llave bajo la maceta / para que vuelvas sin tocar a nadie. / Cada noche la reviso: / sigue ahí, tibia de esperarte.»"
PF = "«En la esquina el farol sigue apagado. / Los vecinos pasan, miran, / y buscan los pasos en la sombra / como quien palpa una pared sin puerta.»"

L(OA4, 2,
  "Aprenderé a localizar las evidencias decisivas de un poema para interpretar un símbolo y a probar esa interpretación con la totalidad del poema.",
  ["Identifico al hablante, el tema y la actitud.", "Sé citar un verso como evidencia."],
  ["Un símbolo es un elemento concreto del poema (un objeto, un lugar, un animal, una luz) que representa una idea abstracta, como la esperanza, el paso del tiempo o el regreso. Una llave puede ser solo una llave, pero en un poema puede simbolizar el acceso a algo o la confianza en que alguien vuelva. Lo decide el conjunto del poema, no una lista de símbolos aprendida de memoria.",
   "Para interpretar un símbolo se buscan evidencias decisivas: los versos que más pesan para sostener la lectura. Sirven la repetición del elemento, los verbos que lo rodean, lo que el hablante siente ante él y lo que ocurre antes y después. Una evidencia es decisiva cuando, sin ella, la interpretación quedaría floja. Una cita que solo nombra el objeto, sin mostrar cómo se relaciona con el tema, no alcanza.",
   "Una interpretación sólida se prueba con la totalidad del poema: debe tener sentido con todo el texto, no solo con un verso. Pregúntate: ¿esta lectura explica también el inicio y el cierre?, ¿deja versos sin sentido? Si dos lecturas son posibles, se prefiere la que se apoya en más versos y deja menos versos sin explicar. Un símbolo puede tener más de un significado, pero siempre con respaldo en el texto."],
  [("símbolo", "elemento concreto que representa una idea abstracta"), ("evidencia decisiva", "verso que más pesa para sostener una interpretación"), ("interpretación", "explicación del sentido de un símbolo o del poema, apoyada en el texto"), ("totalidad", "el poema completo, con todos sus versos")],
  [("Interpretar un símbolo con evidencias", f"Poema de ejemplo: {PC} ¿Qué puede simbolizar el puente?",
    ["El elemento concreto que domina el poema es el puente.", "«Atrás quedó la casa vieja» y «delante, una orilla sin nombre» muestran un paso entre un lugar conocido y otro incierto; «cruje, pero sostiene» muestra inseguridad con apoyo.", "Con esas evidencias, el puente simboliza el paso de una etapa conocida a otra desconocida."],
    "El paso de una etapa conocida a otra incierta"),
   ("Probar una lectura con la totalidad", f"Con el mismo poema, {PC} un lector dice que el puente simboliza el dinero. ¿Se sostiene?",
    ["Busco versos sobre dinero: no hay ninguno.", "Esa lectura deja sin explicar «la casa vieja» y «la orilla sin nombre».", "No se sostiene: no tiene evidencias y no explica la totalidad."],
    "No se sostiene: sin evidencias y dejando versos sin explicar")],
  [("Interpretar un símbolo porque «siempre significa lo mismo» (el mar es la muerte, la rosa es el amor).", "El sentido de un símbolo depende de cada poema.", "Busca en el texto los versos que lo rodean antes de decidir."),
   ("Citar solo el verso donde aparece el objeto como si ya fuera una prueba.", "Nombrar el objeto no muestra qué representa.", "Cita también el verso que lo relaciona con el tema o con lo que siente el hablante.")],
  ([E("¿Qué es un símbolo en un poema? A) un elemento concreto que representa una idea abstracta B) una palabra que se repite varias veces en el poema", "A) un elemento concreto que representa una idea abstracta", "Así se definió en la clase: un objeto o lugar que representa algo como la esperanza."),
    E("¿Qué es una evidencia decisiva? A) el verso que más pesa para sostener una interpretación B) el verso que aparece primero en el poema y presenta el tema", "A) el verso que más pesa para sostener una interpretación", "Se llama decisiva porque, sin ella, la lectura quedaría floja."),
    E("De estas palabras de un poema, ¿cuál es un elemento concreto que podría funcionar como símbolo? A) farol B) esperanza C) tristeza", "A) farol", "Un símbolo es concreto; la esperanza y la tristeza son ideas abstractas.")],
   [E(f"Poema de ejemplo: {PK} ¿Qué idea abstracta representa la llave? A) la confianza en que alguien volverá B) el miedo a los ladrones C) el deseo de abandonar la casa", "A) la confianza en que alguien volverá", "Se deja «para que vuelvas» y se revisa cada noche «tibia de esperarte»: representa la espera confiada."),
    E(f"Poema de ejemplo: {PF} ¿Qué pareja de versos es más decisiva para decir que el farol apagado simboliza la falta de guía? A) «buscan los pasos en la sombra / como quien palpa una pared sin puerta» B) «En la esquina el farol sigue apagado», porque es el verso donde aparece el farol", "A) «buscan los pasos en la sombra / como quien palpa una pared sin puerta»", "Muestran la desorientación de los vecinos; el primer verso solo nombra el farol."),
    E("Para interpretar el símbolo del sol en un poema, ¿cuál es mejor evidencia? A) un verso donde el sol «llega a deshacer la noche larga» B) la opinión general de que el sol da alegría a todas las personas", "A) un verso donde el sol «llega a deshacer la noche larga»", "Una evidencia debe salir del poema; el gusto general no prueba nada sobre ese texto.")],
   [E("Poema de ejemplo: «La higuera del fondo nadie la poda. / Crece torcida, rompe el muro, / y cada verano me regala higos / como quien perdona sin pedir nada.» ¿Qué interpretación se apoya en los dos últimos versos? A) la higuera simboliza una generosidad que da sin pedir nada B) la higuera simboliza el rencor del hablante hacia el muro C) la higuera simboliza el apuro por podar", "A) la higuera simboliza una generosidad que da sin pedir nada", "«Me regala higos» y «como quien perdona sin pedir nada» muestran un dar sin condiciones."),
    E("Poema de ejemplo: «Mi hermana cerró la ventana / y desde entonces el cuarto huele a lluvia guardada. / Yo golpeo suave la madera, / pero ella no gira la cabeza.» ¿Qué verso muestra que la ventana cerrada simboliza una distancia entre las hermanas? A) «Yo golpeo suave la madera, pero ella no gira la cabeza» B) «el cuarto huele a lluvia guardada desde que ella cerró la ventana»", "A) «Yo golpeo suave la madera, pero ella no gira la cabeza»", "Es el único verso que muestra a las dos personas sin comunicarse; el otro solo describe el encierro."),
    E("Poema de ejemplo: «El tren de las seis pasa sin parar. / Yo lo veo desde el andén, / con el boleto doblado en la mano, / y no sé si me alegra o me duele / que nunca me haya esperado.» ¿Qué lectura se apoya en más versos? A) el tren simboliza una oportunidad que pasa sin detenerse y el boleto muestra que el hablante quería tomarla B) el tren simboliza la rapidez de la tecnología moderna y el boleto, el precio de los pasajes", "A) el tren simboliza una oportunidad que pasa sin detenerse y el boleto muestra que el hablante quería tomarla", "Explica el tren que no para, el boleto en la mano y la duda final; la otra lectura no tiene ningún verso que la respalde.")],
   [E("Poema de ejemplo: «Subo la escalera de mi casa / contando los peldaños que crujen. / Arriba no hay nadie: / solo el eco de mis pasos, / y una puerta que no quiero abrir.» Lectura 1: la escalera simboliza el ascenso en el trabajo. Lectura 2: la escalera simboliza el acercamiento a algo que da miedo enfrentar. ¿Cuál se sostiene mejor con la totalidad? A) la lectura 2 B) la lectura 1", "A) la lectura 2", "Explica la soledad del lugar y la puerta que el hablante no quiere abrir; la lectura 1 no explica esos versos."),
    E("Un estudiante afirma: «El mar siempre simboliza la muerte en cualquier poema». ¿Qué falla en esa afirmación? A) el significado de un símbolo depende de cada poema y de sus versos B) nada: los símbolos tienen siempre un significado único y universal", "A) el significado de un símbolo depende de cada poema y de sus versos", "Se interpreta con las pistas del texto, no con una lista fija.")],
   [E("Poema de ejemplo: «Vendimos la casa en marzo. / El árbol del patio se quedó con los otros dueños. / En la mudanza solo cupo el reloj de la abuela / y su tic-tac, que ahora cuelga de otra pared.» ¿Qué puede simbolizar el reloj? A) la memoria de la familia que se lleva a otra casa B) el apuro de la familia por terminar la mudanza a tiempo C) el deseo de volver a comprar la casa con el árbol del patio", "A) la memoria de la familia que se lleva a otra casa", "Es lo único que «cupo» al irse de la casa y sigue sonando en otro lugar: conserva el recuerdo."),
    E("Poema de ejemplo: titulado «Barco de papel»: «Hice un barco con la hoja de un cuaderno / y lo puse en el agua de la calle. / Se fue torcido, pero se fue.» Dos lectores interpretan el barco. Lector 1: simboliza un primer intento imperfecto que igual avanza. Lector 2: simboliza el tamaño del cuaderno. ¿Cuál tiene respaldo en los versos? A) el lector 1, por «se fue torcido, pero se fue» B) el lector 2, por «la hoja de un cuaderno»", "A) el lector 1, por «se fue torcido, pero se fue»", "Ese verso muestra imperfección y avance; nombrar el cuaderno solo indica el material.")]),
   [E("En un taller de poesía se lee: «En casa abrí el paraguas / aunque no llueve: / hoy necesito un techo / que yo misma pueda mover.» Estudiante 1: el paraguas simboliza el deseo de protección y de autonomía. Estudiante 2: el paraguas simboliza el estado del clima. ¿Cuál interpretación está respaldada? A) la del estudiante 1, por «un techo que yo misma pueda mover» B) la del estudiante 2, porque el poema menciona la palabra «llueve» y el clima", "A) la del estudiante 1, por «un techo que yo misma pueda mover»", "El verso une protección (techo) con decisión propia (mover); además el poema dice que no llueve.")],
  [E("Una interpretación de un símbolo es sólida cuando… A) se apoya en versos y tiene sentido con todo el poema B) coincide con lo que opina la mayoría del curso", "A) se apoya en versos y tiene sentido con todo el poema", "La solidez viene del texto, no de la cantidad de personas que opinan igual."),
   E("Si una lectura deja varios versos sin explicar, ¿qué conviene pensar? A) que probablemente exista una interpretación mejor B) que no importa, porque basta con que explique un verso importante", "A) que probablemente exista una interpretación mejor", "La totalidad del poema es la prueba de una lectura."),
   E("¿Cómo se decide qué representa una llave dentro de un poema? A) con las pistas del poema completo B) con una lista fija de símbolos", "A) con las pistas del poema completo", "El sentido del símbolo lo da el texto en el que aparece.")],
  ("Lee este poema de ejemplo: «Hice un farol con una lata vacía / y lo colgué de la rama del limonero. / Esa noche el patio tuvo un cielo pequeño. / Mi padre salió, miró, y no dijo nada; / solo dejó la puerta abierta.» Escribe: 1) el elemento concreto que puede ser un símbolo, 2) dos versos que sean evidencia decisiva, 3) tu interpretación en una oración y 4) una comprobación con otro verso de que tu lectura tiene sentido con la totalidad.",
   "1) El farol de lata. 2) «Esa noche el patio tuvo un cielo pequeño» y «solo dejó la puerta abierta». 3) El farol simboliza un gesto creativo del hablante que logra iluminar su espacio y ser aceptado. 4) Con «mi padre salió, miró, y no dijo nada» se entiende que la aceptación llega sin palabras, y eso calza con mi lectura.",
   ["nombra un elemento concreto", "cita dos versos como evidencia", "formula una interpretación clara", "la prueba con otro verso"], ["cuatro respuestas numeradas"], ["interpretar sin citar versos", "citar versos que no se relacionan con la lectura"],
   "Comprueba que cada verso citado exista en el poema y que tu interpretación no deje versos sin explicar."),
  "Escoge un objeto de tu casa y escribe dos versos propios donde pueda leerse como símbolo de una idea.",
  "Escribe dos interpretaciones distintas del puente del primer poema de la clase y señala cuál se apoya en más versos.")

# ------------------------------------------------------------------ OA 04 · clase 3
L(OA4, 3,
  "Aprenderé a identificar el lenguaje figurado y las repeticiones de un poema (palabras, estructuras, sonidos o ideas) y a explicar el efecto que producen.",
  ["Reconozco versos y estrofas.", "Sé que las palabras pueden tener sentido literal y sentido figurado."],
  ["El lenguaje figurado usa las palabras con un sentido distinto del literal (el que dicen tal cual) para crear imágenes. La comparación une dos cosas con un nexo, una palabra que une, como «como» o «parece» («tus manos, como nidos»). La metáfora las identifica sin nexo («tus manos son nidos»). La personificación da rasgos humanos a algo que no lo es («la tarde se sienta, cansada»). La hipérbole exagera para intensificar un sentimiento («te esperé mil años»).",
   "Las repeticiones son otro recurso. Se puede repetir una palabra o una estructura, como en la anáfora, que ocurre cuando varios versos comienzan igual. También se repiten sonidos: la aliteración es la repetición de un mismo sonido consonante, y la rima es la coincidencia de sonidos al final de los versos. Además, una misma idea puede volver con otras palabras. La repetición da ritmo y, sobre todo, insiste: hace notar lo que al hablante le importa.",
   "No basta con nombrar el recurso: hay que explicar su efecto, que depende del poema. Una personificación puede volver cercano un paisaje; una anáfora puede dar insistencia, urgencia o ternura; una hipérbole puede mostrar la intensidad de un sentimiento. Una buena explicación sigue tres pasos: cita el pasaje, nombra el recurso y relaciona su efecto con el tema o con la actitud del hablante."],
  [("lenguaje figurado", "uso de palabras con un sentido distinto del literal para crear imágenes"), ("comparación", "figura que une dos cosas con un nexo como «como» o «parece»"), ("metáfora", "figura que identifica una cosa con otra sin nexo"), ("personificación", "figura que da rasgos humanos a algo que no es humano"), ("hipérbole", "exageración que intensifica"), ("anáfora", "repetición de una palabra o estructura al inicio de varios versos"), ("aliteración", "repetición de un mismo sonido consonante"), ("efecto", "impresión que produce un recurso en el lector")],
  [("Figuras en un fragmento", "Fragmento de ejemplo: «Tus palabras son llaves de agua: abren lo que estaba seco. La tarde, cansada, se sienta en el muelle.» ¿Qué figuras aparecen y qué efecto tienen?",
    ["«Tus palabras son llaves de agua» identifica palabras con llaves sin nexo: es una metáfora.", "«La tarde, cansada, se sienta» da rasgos humanos a la tarde: es una personificación.", "La metáfora muestra que las palabras alivian; la personificación vuelve cercana y tranquila la tarde."],
    "Metáfora (las palabras alivian lo seco) y personificación (una tarde tranquila y cercana)"),
   ("Anáfora y su efecto", "Poema de ejemplo: «Por la ventana entra el pan, / por la ventana entra el sol, / por la ventana entra mi madre / con las manos llenas de día.» ¿Qué repetición hay y qué efecto produce?",
    ["Tres versos comienzan con «por la ventana entra»: es una anáfora.", "Cada vez entra algo más querido: el pan, el sol, la madre.", "El efecto es insistir en la ventana como lugar donde llega lo cotidiano y dar un tono tierno al poema."],
    "Anáfora de «por la ventana entra»: insiste en lo cotidiano que llega y da ternura")],
  [("Nombrar la figura sin explicar su efecto («aquí hay una metáfora»).", "No se explica qué aporta al poema.", "Agrega: «lo que produce es…» y relaciónalo con el tema o la actitud."),
   ("Confundir comparación y metáfora.", "Ambas relacionan dos cosas, pero la comparación usa un nexo y la metáfora no.", "Busca «como», «parece» o «igual que»: si están, es comparación.")],
  ([E("En «La noche es un río oscuro», ¿qué figura hay? A) metáfora B) comparación", "A) metáfora", "Identifica la noche con un río sin usar un nexo."),
    E("En «Corre el viento como un potro sin dueño», ¿qué figura hay? A) comparación B) metáfora", "A) comparación", "El nexo «como» une el viento con un potro."),
    E("¿Qué es la anáfora? A) la repetición de una palabra o estructura al comienzo de varios versos B) la coincidencia de vocales y consonantes al final de dos o más versos", "A) la repetición de una palabra o estructura al comienzo de varios versos", "La coincidencia de sonidos finales se llama rima.")],
   [E("Verso de ejemplo: «La campana se despierta bostezando sobre la plaza». ¿Qué figura hay? A) personificación B) hipérbole C) comparación", "A) personificación", "A la campana se le atribuyen acciones humanas: despertarse y bostezar."),
    E("Verso de ejemplo: «Te esperé mil años en la puerta». ¿Qué figura hay y qué muestra? A) hipérbole: exagera para mostrar lo larga que se sintió la espera B) metáfora: identifica la espera con un tiempo muy largo sin usar nexo", "A) hipérbole: exagera para mostrar lo larga que se sintió la espera", "Nadie espera mil años: la cifra exagera para intensificar el sentimiento."),
    E("Verso de ejemplo: «Susurran las sábanas, suave el sueño se sosiega». ¿Qué sonido se repite y qué efecto sugiere? A) la /s/, que sugiere un susurro suave B) la /r/, que sugiere un golpe fuerte", "A) la /s/, que sugiere un susurro suave", "La /s/ aparece en casi todas las palabras y el verso habla de susurrar y sosegar.")],
   [E("Poema de ejemplo: «Hoy la calle me abraza con su ruido, / hoy la calle me enseña sus esquinas, / hoy la calle me presta su ventana.» ¿Qué repetición organiza estos versos y qué efecto tiene? A) una anáfora de «hoy la calle me…», que insiste en una cercanía afectuosa B) una rima final, que marca el término de cada verso y de la estrofa", "A) una anáfora de «hoy la calle me…», que insiste en una cercanía afectuosa", "Los tres versos comienzan igual y todos muestran a la calle acercándose al hablante."),
    E("Verso de ejemplo: «El miedo es un perro que me sigue a todas partes». ¿Qué figura es y qué sugiere? A) metáfora: presenta el miedo como un perro que acompaña sin soltarlo B) comparación: el nexo «es» une el miedo con un perro que lo sigue C) personificación: el perro tiene rasgos humanos porque sigue al hablante", "A) metáfora: presenta el miedo como un perro que acompaña sin soltarlo", "No hay nexo, sino una identificación directa, y el verbo «sigue» muestra una compañía constante."),
    E("¿Cuál explicación sigue los tres pasos (cita, recurso y efecto) para «La luna se puso su abrigo de nubes»? A) Cita «la luna se puso su abrigo de nubes», personificación: la luna se abriga como una persona, lo que vuelve acogedora la noche B) Dice que en este verso hay una figura muy bonita que mejora el poema y gusta a los lectores C) Dice que es una comparación porque la luna se compara con una persona, pero no cita el verso ni explica el efecto", "A) Cita «la luna se puso su abrigo de nubes», personificación: la luna se abriga como una persona, lo que vuelve acogedora la noche", "Es la única que cita, nombra la figura y explica su efecto.")],
   [E("Un estudiante dice que «Eres dulce como la miel» es una metáfora. ¿Qué falla en su respuesta? A) usa el nexo «como», por lo que es una comparación B) es una hipérbole porque exagera lo dulce que es la persona", "A) usa el nexo «como», por lo que es una comparación", "La presencia de «como» distingue la comparación de la metáfora."),
    E("Poema de ejemplo: «Llueve y llueve y llueve sobre el techo, / llueve sobre el barrio, sobre el pecho.» ¿Qué efecto tiene la repetición de «llueve»? A) sugiere una lluvia que no cesa y que alcanza al hablante B) solo ayuda a completar la medida del verso sin aportar un sentido", "A) sugiere una lluvia que no cesa y que alcanza al hablante", "La insistencia imita la continuidad de la lluvia, que llega «sobre el pecho».")],
   [E("Versos de ejemplo: «Tu risa es una cascada que me despierta; el sol, tímido, asoma por mi ventana.» ¿Qué figuras aparecen? A) metáfora y personificación B) comparación e hipérbole C) metáfora e hipérbole", "A) metáfora y personificación", "«Tu risa es una cascada» es metáfora; «el sol, tímido, asoma» da un rasgo humano al sol."),
    E("Versión 1: «Estoy muy cansado.» Versión 2: «Mis pies son dos anclas que me arrastran al sueño.» ¿Qué aporta la versión 2? A) una imagen que muestra el peso del cansancio mediante una metáfora B) una comparación que usa el nexo «como» para describir el cansancio", "A) una imagen que muestra el peso del cansancio mediante una metáfora", "Los pies pasan a ser anclas: el cansancio se vuelve algo pesado que hunde.")]),
   [E("En un taller se lee: «Aquí la nieve no cae: aterriza, / aquí la nieve no cae: descansa, / aquí la nieve no cae: perdona.» ¿Qué efecto tiene la anáfora «aquí la nieve no cae»? A) insiste en ver la caída de la nieve como algo suave y amable, no violento B) indica que el poema cambia de tema cada vez que se repite el verso", "A) insiste en ver la caída de la nieve como algo suave y amable, no violento", "Cada repetición agrega un verbo amable: aterriza, descansa, perdona.")],
  [E("¿Cuál es la diferencia entre metáfora y comparación? A) la comparación usa un nexo como «como»; la metáfora no B) la metáfora exagera la realidad y la comparación la describe tal cual", "A) la comparación usa un nexo como «como»; la metáfora no", "El nexo es lo que las distingue."),
   E("Al explicar un recurso, ¿qué se hace además de nombrarlo? A) citar el pasaje y explicar su efecto B) copiar el poema completo y subrayar todas las figuras", "A) citar el pasaje y explicar su efecto", "Los tres pasos son citar, nombrar el recurso y explicar su efecto."),
   E("¿Qué es la aliteración? A) la repetición de un mismo sonido consonante B) la repetición de un verso completo al final del poema", "A) la repetición de un mismo sonido consonante", "Así se definió en esta clase.")],
  ("Lee este poema de ejemplo: «Mi calle es un río de gente que corre. / Mi calle me llama por mi nombre, / mi calle me espera, mi calle me empuja, / mi calle se cansa cuando anochece.» Escribe: 1) una metáfora que encuentres y qué sugiere, 2) una repetición (de palabra o estructura) y su efecto, 3) una personificación y qué aporta.",
   "1) «Mi calle es un río de gente que corre» sugiere un flujo constante de personas. 2) La anáfora «mi calle» al inicio de varios versos insiste en la cercanía del hablante con su calle. 3) «Mi calle se cansa cuando anochece» da un rasgo humano a la calle y la vuelve viva y cercana.",
   ["encuentra la metáfora", "identifica una repetición y explica su efecto", "señala una personificación con su aporte"], ["tres respuestas con cita"], ["nombrar figuras sin explicar su efecto", "confundir comparación y metáfora"],
   "Revisa que cada respuesta tenga cita, nombre del recurso y efecto."),
  "Busca en una canción o poema que tengas en casa una repetición y anota qué efecto crees que tiene.",
  "Escribe cuatro versos con una anáfora y una personificación sobre el mismo lugar.")

# ------------------------------------------------------------------ OA 04 · clase 4
PR = "«Cada mañana barro la vereda / y el viento devuelve las hojas. / Otro, en mi lugar, habría desistido. / Yo sigo: barro, y barro, y barro. / No es el suelo lo que limpio: / es la costumbre de no rendirme.»"
PCU = "«Mi cuaderno tiene una página rota. / Antes me daba rabia mirarla. / Ahora, por esa rotura, / entra la luz de la lámpara.»"

L(OA4, 4,
  "Aprenderé a relacionar un fragmento con el total del poema y a contrastar distintas interpretaciones para decidir cuál se apoya mejor en el texto.",
  ["Interpreto símbolos con evidencias del poema.", "Identifico recursos y explico su efecto."],
  ["Un fragmento (un verso o una estrofa) se entiende bien solo en relación con el total del poema. Se pregunta: ¿qué función cumple aquí?, ¿presenta la situación, desarrolla una idea, introduce un giro o cierra el poema? Un giro es un cambio de rumbo o de actitud. Los versos finales suelen cambiar el sentido de lo anterior: un barrido que parecía una simple tarea puede resultar una forma de perseverar.",
   "Un poema admite más de una interpretación, pero no cualquiera. Para contrastar dos lecturas se comparan tres cosas: cuántos versos apoya cada una, si deja versos sin explicar y si respeta la actitud del hablante. Se llama interpretación plausible a la que se sostiene con el texto, aunque otra también sea posible. No se trata de que «gane» una lectura única, sino de ver cuál tiene mejor respaldo.",
   "Al discutir con otro lector conviene reconocer lo válido de su lectura, señalar qué versos la respaldan o no, y decir si la tuya cambia. Cambiar de interpretación tras releer el texto no es perder: es leer con más precisión. Evita frases como «para mí significa eso» cuando no hay versos que lo apoyen."],
  [("fragmento", "parte de un poema, como un verso o una estrofa"), ("giro", "cambio de rumbo o de actitud dentro del poema"), ("interpretación plausible", "lectura que se sostiene con el texto aunque otra sea posible"), ("contrastar", "comparar dos lecturas para ver cuál tiene mejor respaldo")],
  [("Función del fragmento final", f"Poema de ejemplo: {PR} ¿Qué función cumplen los dos últimos versos en el total del poema?",
    ["Los cuatro primeros versos cuentan una acción repetida: barrer aunque el viento devuelva las hojas.", "Los dos últimos pasan de lo literal (el suelo) a lo figurado (la costumbre de no rendirse): hay un giro.", "Ese cierre revela el sentido del poema: la perseverancia."],
    "Introducen un giro que revela el sentido figurado: barrer es una forma de no rendirse"),
   ("Contrastar dos lecturas", f"Con el mismo poema, {PR} la lectura 1 dice «el hablante muestra perseverancia». La lectura 2 dice «el hablante está harto de un trabajo inútil». ¿Cuál es más plausible?",
    ["La lectura 2 se apoya en «el viento devuelve las hojas» y en la repetición «barro, y barro, y barro», que sugiere cansancio.", "Pero no explica «otro habría desistido» ni «la costumbre de no rendirme».", "La lectura 1 explica todos los versos; la 2 aporta un matiz de cansancio."],
    "La lectura 1: explica más versos; la 2 solo suma el matiz del cansancio")],
  [("Leer un verso suelto y decidir el sentido de todo el poema.", "El sentido de un fragmento depende de lo que viene antes y después.", "Relee el poema completo y pregunta qué función cumple el fragmento."),
   ("Decir «cada lector tiene su verdad» para no revisar las evidencias.", "Una lectura que deja versos sin explicar es menos plausible que otra que los explica.", "Compara cuántos versos apoya cada lectura y cuáles quedan sin explicar.")],
  ([E("¿Qué es un giro en un poema? A) un cambio de rumbo o de actitud a mitad del poema B) la rima que se produce en el último verso del poema", "A) un cambio de rumbo o de actitud a mitad del poema", "Un giro modifica la dirección del poema; la rima es un recurso sonoro."),
    E("Para entender un fragmento, ¿qué conviene hacer? A) leerlo en relación con el total del poema B) leerlo solo, porque cada verso tiene su propio sentido", "A) leerlo en relación con el total del poema", "El sentido del fragmento depende de la función que cumple dentro del conjunto."),
    E("En un poema de tres estrofas, la primera presenta una calle vacía, la segunda cuenta que alguien la recorre y la tercera dice que ya no está sola. ¿Qué función cumple la tercera? A) cierra el poema mostrando un cambio B) presenta por primera vez la situación inicial", "A) cierra el poema mostrando un cambio", "La última estrofa culmina el recorrido y muestra cómo cambió la calle.")],
   [E(f"Poema de ejemplo: {PCU} ¿Qué giro hay? A) de la rabia ante la rotura a verla como entrada de luz B) de la alegría por la página nueva a la tristeza por romperla", "A) de la rabia ante la rotura a verla como entrada de luz", "«Antes» y «ahora» marcan el cambio: la rotura que daba rabia deja pasar la luz."),
    E("¿Qué es una interpretación plausible? A) la que se sostiene con el texto aunque otra lectura sea posible B) la única que es correcta, la que pensó el autor del poema", "A) la que se sostiene con el texto aunque otra lectura sea posible", "Un poema admite varias lecturas, siempre que tengan respaldo en el texto."),
    E("Al contrastar dos lecturas, ¿qué se compara? A) cuántos versos apoya cada una, si deja versos sin explicar y si respeta la actitud del hablante B) qué lectura es más original, cuál es más corta y cuál gusta a más compañeros", "A) cuántos versos apoya cada una, si deja versos sin explicar y si respeta la actitud del hablante", "Los criterios salen del poema, no de quién lee.")],
   [E("Poema de ejemplo: «Los zapatos de mi hermano me quedaban grandes. / Los usé con papeles en la punta, / caminé como en puntillas por el patio. / Hoy me quedan justos, / y él ya no está para verlo.» ¿Qué introduce el último verso? A) una pérdida: el orgullo de haber crecido se mezcla con tristeza B) la confirmación de que el poema solo trata de zapatos y de la talla del hermano", "A) una pérdida: el orgullo de haber crecido se mezcla con tristeza", "«Ya no está para verlo» cambia el tono de la estrofa anterior y agrega una ausencia."),
    E(f"Con este poema de ejemplo, {PCU} la lectura 1 dice que el hablante aprende a ver una imperfección como lo que deja pasar la luz. La lectura 2 dice que el hablante odia su cuaderno. ¿Cuál es plausible? A) la 1, por «ahora, por esa rotura, entra la luz» B) la 2, por «me daba rabia mirarla», que muestra odio hacia el cuaderno", "A) la 1, por «ahora, por esa rotura, entra la luz»", "La rabia es del pasado («antes»); el presente del poema es la luz que entra."),
    E("Poema de ejemplo: «Escribí una carta larga, de mil excusas. / La doblé, la guardé en el cajón. / A la mañana siguiente la rompí / y escribí solo: “perdón”.» ¿Qué hace el último verso respecto del resto? A) contrasta con las mil excusas y resume lo esencial B) repite lo dicho en los primeros versos con otras palabras", "A) contrasta con las mil excusas y resume lo esencial", "Una sola palabra reemplaza la carta larga: el cierre cambia el sentido del esfuerzo anterior.")],
   [E("Poema de ejemplo «La cuerda»: «Tiro de la cuerda de la campana / y el sonido se va sin pedirme permiso. / Tiro otra vez, y otra, y otra. / Tal vez alguien en el cerro me escucha. / Tal vez solo soy yo, llamándome.» Julia dice que el poema trata de soledad, por «solo soy yo, llamándome». Luis dice que también trata de esperanza de ser escuchado, por «tal vez alguien en el cerro me escucha». Julia relee y propone «soledad y esperanza a la vez». ¿Qué hace? A) integra lo válido de ambas lecturas con versos del poema B) abandona su lectura porque Luis la convenció con más fuerza", "A) integra lo válido de ambas lecturas con versos del poema", "Ambas lecturas tienen respaldo, y el poema las contiene a las dos en sus dos últimos versos."),
    E("Una compañera dice: «El verso final de un poema no importa; el sentido siempre está al principio». ¿Qué argumento la contradice? A) los versos finales suelen introducir un giro o cerrar el sentido del total B) los poemas siempre explican su sentido en la última palabra del último verso", "A) los versos finales suelen introducir un giro o cerrar el sentido del total", "Como se vio en la clase, el cierre puede cambiar la lectura de todo lo anterior.")],
   [E("Poema de ejemplo: «Planté un nombre en la arena / y lo cuidé con las dos manos. / Vino la ola, lo borró suave, / y yo aprendí que a veces / el mar también sabe leer.» ¿Qué función cumplen los dos últimos versos? A) transforman la pérdida en aprendizaje: el mar «lee» el nombre antes de borrarlo B) repiten que el nombre se borró y que el hablante perdió lo que había cuidado", "A) transforman la pérdida en aprendizaje: el mar «lee» el nombre antes de borrarlo", "Hay un giro: lo que parecía solo destrucción se interpreta como una lectura del nombre."),
    E("Poema de ocho versos. La lectura 1 explica los versos 1 a 6. La lectura 2 explica solo los versos 7 y 8, y deja sin sentido los otros seis. ¿Cuál es más plausible? A) la lectura 1, porque deja menos versos sin explicar B) la lectura 2, porque explica con detalle el final del poema", "A) la lectura 1, porque deja menos versos sin explicar", "Una lectura mejor respaldada explica más versos de la totalidad.")]),
   [E("Poema de ejemplo: «La escuela en febrero tiene eco. / Los pasillos aprenden a callar. / Un portón entreabierto espera / con la paciencia de los que saben volver.» Lectura 1: el poema anticipa el regreso de los estudiantes. Lectura 2: el poema dice que la escuela fue abandonada para siempre. ¿Cuál está mejor respaldada? A) la 1, por «espera con la paciencia de los que saben volver» B) la 2, por «tiene eco» y por «los pasillos aprenden a callar»", "A) la 1, por «espera con la paciencia de los que saben volver»", "El portón entreabierto que espera apunta a un regreso; el eco solo muestra el vacío temporal.")],
  [E("¿Qué función puede cumplir la estrofa final de un poema? A) cerrar el poema, a veces con un giro que cambia el sentido de lo anterior B) repetir siempre, con otras palabras, lo que ya dijo la primera estrofa", "A) cerrar el poema, a veces con un giro que cambia el sentido de lo anterior", "El cierre suele resignificar lo dicho antes."),
   E("¿Un poema admite una sola interpretación válida? A) no: admite varias, siempre que se apoyen en el texto B) sí, solo la que el autor tenía en mente al escribirlo", "A) no: admite varias, siempre que se apoyen en el texto", "La plausibilidad depende de las evidencias del poema."),
   E("Cambiar de interpretación después de releer el poema es… A) leer con más precisión B) un error que hay que evitar", "A) leer con más precisión", "Revisar la lectura con el texto a la vista mejora el análisis.")],
  ("Lee este poema de ejemplo: «Mi vecina riega el cemento / de su patio sin macetas. / Dice que algún día / el agua se acordará de las flores.» Lectura A: la vecina mantiene un gesto de cuidado con la esperanza de que algo cambie. Lectura B: la vecina está confundida y pierde su tiempo. Escribe: 1) qué función cumplen los dos últimos versos, 2) cuál lectura es más plausible y por qué, citando dos versos, 3) qué rescatas de la otra lectura.",
   "1) Los dos últimos versos dan el motivo de su gesto: explican por qué riega, y cierran con una esperanza. 2) La lectura A es más plausible: «dice que algún día el agua se acordará de las flores» muestra que espera un cambio y «riega» muestra cuidado; la lectura B no explica esos versos. 3) De la lectura B rescato que el gesto parece inútil porque no hay macetas, lo que da un tono de ternura y de ironía suave.",
   ["explica la función del cierre", "elige una lectura y la respalda con dos versos", "reconoce lo válido de la otra"], ["tres respuestas en el cuaderno"], ["decidir sin citar versos", "descartar la otra lectura sin reconocer nada válido"],
   "Verifica que los versos citados estén en el poema y que cada lectura sea comparada con los mismos versos."),
  "Lee un poema de tu casa o del liceo y escribe dos lecturas posibles; marca cuál se apoya en más versos.",
  "Escribe un poema de seis versos cuyo último verso cambie el sentido de los cinco anteriores y explica el giro.")

# ------------------------------------------------------------------ OA 04 · clase 5
SON = "«Aprendo de la orilla a esperar, / sin prisa, sin querella ni razón, / mientras la ola dicta su canción / y la espuma se pone a descansar. // La arena sabe bien cómo guardar / el rastro leve de cada ilusión, / y el viento, con su gesto de perdón, / se acerca, suavemente, a borrar. // Si un día no consigo decidir, / me quedo al borde, sin melancolía, / y dejo que la tarde vuelva a abrir // lo que el apuro cerró en mi alegría. / Entonces sé que esperar es seguir, / y que el mar, paciente, es mi compañía.»"
RESP = "«“Aprendo de la orilla a esperar”, dice el soneto que leí. / Yo aprendo de la orilla a partir: / la ola nunca pregunta si el puerto la espera.»"

L(OA4, 5,
  "Aprenderé las características del soneto y a situar un poema en relación con otros textos (intertextualidad), explicando cómo la forma y las relaciones aportan al sentido.",
  ["Explico la función de un fragmento en el total del poema.", "Reconozco rima y estrofas."],
  ["El soneto es una forma poética tradicional que han usado poetas de lengua española durante siglos. Tiene 14 versos organizados en cuatro estrofas: dos cuartetos (de cuatro versos) y dos tercetos (de tres versos). Lo habitual es que los versos tengan once sílabas y rimen en consonante, es decir, que coincidan vocales y consonantes desde la última vocal acentuada (por ejemplo, esperar y descansar). En los cuartetos el esquema clásico es ABBA ABBA; en los tercetos hay varias combinaciones, como CDC DCD.",
   "La forma también organiza el pensamiento. En muchos sonetos los cuartetos plantean una situación o una idea, y los tercetos la desarrollan o la cierran con un giro o una conclusión. Analizar un soneto es relacionar su forma con su sentido: por qué esa estructura, qué hace cada estrofa. Contar versos sin explicar qué aportan no es analizar. Una forma fija tampoco obliga a decir lo mismo: cada poema usa el molde para decir algo propio. Los sonetos de ejemplo de este cuaderno sirven para analizar estrofas, rima y sentido; no se pide contar sílabas.",
   "Un texto también se entiende en relación con otros. La intertextualidad es la relación de un texto con otras obras: puede citar, aludir (hacer una referencia indirecta), retomar un tema o una forma, o responder a otro texto. Para analizarla se pregunta: ¿con qué texto se relaciona?, ¿qué retoma?, ¿qué cambia y qué efecto tiene ese cambio? Si el texto relacionado no está a la vista, no se puede afirmar que haya intertextualidad."],
  [("soneto", "poema de 14 versos en dos cuartetos y dos tercetos, con rima consonante"), ("cuarteto", "estrofa de cuatro versos"), ("terceto", "estrofa de tres versos"), ("rima consonante", "coincidencia de vocales y consonantes desde la última vocal acentuada"), ("intertextualidad", "relación de un texto con otros textos"), ("aludir", "hacer una referencia indirecta a algo")],
  [("Forma y sentido de un soneto", f"Soneto de ejemplo: {SON} Describe su estructura y qué hace cada parte.",
    ["Cuento 14 versos en cuatro estrofas: dos cuartetos y dos tercetos.", "Las palabras finales de los cuartetos son esperar, razón, canción, descansar / guardar, ilusión, perdón, borrar: el esquema es ABBA ABBA; los tercetos siguen CDC DCD (decidir, melancolía, abrir / alegría, seguir, compañía).", "Los cuartetos muestran lo que enseña la orilla; los tercetos pasan al hablante y concluyen que «esperar es seguir»: ese es el giro."],
    "14 versos, dos cuartetos y dos tercetos, ABBA ABBA CDC DCD; los cuartetos observan la orilla y los tercetos concluyen con el hablante"),
   ("Reconocer una intertextualidad", f"Poema de ejemplo: {RESP} El soneto al que se refiere se llama «La orilla» y su primer verso es «Aprendo de la orilla a esperar». ¿Qué relación tiene con ese soneto?",
    ["El primer verso del poema cita entre comillas el primer verso del soneto: hay una cita.", "Retoma el tema de la orilla, pero cambia «esperar» por «partir».", "El efecto es dialogar con el soneto y proponer una actitud contraria."],
    "Cita el primer verso del soneto y lo contradice: dialoga con él desde otra actitud")],
  [("Decir que un poema de 14 versos ya es un soneto, sin mirar estrofas ni rima.", "El soneto exige una organización (dos cuartetos y dos tercetos) y rima consonante.", "Comprueba las estrofas y el esquema de rima antes de nombrarlo."),
   ("Afirmar que hay intertextualidad sin tener el otro texto a la vista.", "Sin el texto relacionado no se puede comprobar qué se retoma ni qué cambia.", "Cita el verso o la referencia y compáralos.")],
  ([arith("Un soneto tiene dos cuartetos (de 4 versos cada uno) y dos tercetos (de 3 versos cada uno). ¿Cuántos versos tiene en total?", "2 * 4 + 2 * 3", "Se suman los versos de los cuartetos y los de los tercetos."),
    E("¿Qué es la intertextualidad? A) la relación de un texto con otros textos B) la repetición de sonidos dentro de un verso", "A) la relación de un texto con otros textos", "La repetición de sonidos es un recurso distinto, como la aliteración."),
    E("¿En qué par de palabras hay rima consonante? A) ventana / mañana B) cielo / sueño C) mesa / puerta", "A) ventana / mañana", "Coinciden vocales y consonantes desde la última vocal acentuada: -ana; en cielo / sueño cambian las consonantes.")],
   [E("Cuartetos de ejemplo: «Se apaga la ciudad y el día se aleja, / la noche cierra el paso de la gente; / un perro ladra al fondo, tristemente, / y un farol, solitario, nos aconseja.» ¿Qué esquema de rima siguen? A) ABBA B) ABAB C) AABB", "A) ABBA", "Aleja y aconseja riman entre sí (A); gente y tristemente riman entre sí (B)."),
    E("En un soneto de ejemplo, los cuartetos presentan una ciudad que se queda sin luz y los tercetos concluyen que, aun a oscuras, el barrio se acompaña. ¿Qué función cumplen los tercetos? A) desarrollan la idea y la cierran con una conclusión B) presentan por primera vez la situación inicial", "A) desarrollan la idea y la cierran con una conclusión", "Los tercetos suelen completar o dar un giro a lo planteado en los cuartetos."),
    E("Un poema actual incluye entre comillas un verso de otro poema y luego lo contradice. ¿Qué relación hay entre ambos textos? A) una intertextualidad: cita y respuesta B) una aliteración de sonidos entre dos versos", "A) una intertextualidad: cita y respuesta", "El poema nuevo retoma el verso de otro y responde a él.")],
   [E("Un terceto de ejemplo termina sus versos en estas palabras: pared, camino, red. ¿Qué esquema de rima forman? A) CDC B) CCD", "A) CDC", "Pared y red riman en consonante (C); camino no rima con ellas (D)."),
    E("Texto 1: «Cuando pase el último tren, yo seguiré esperando.» Texto 2: «“Cuando pase el último tren, yo seguiré esperando”, escribió el poeta del andén; yo prefiero comprar el pasaje.» ¿Qué hace el texto 2? A) cita el texto 1 y toma una postura contraria B) copia el texto 1 completo y no agrega ninguna idea nueva", "A) cita el texto 1 y toma una postura contraria", "Comienza con la cita y luego opone «comprar el pasaje» a «seguir esperando»."),
    E("Un grupo escribe un poema de 14 versos en cuatro estrofas: dos de cuatro versos y dos de tres, con rima consonante y esquema ABBA ABBA CDC DCD. ¿Cómo se llama esa forma? A) soneto B) poema en verso libre", "A) soneto", "Cumple las características descritas en la clase: 14 versos, cuartetos, tercetos y rima consonante.")],
   [E("Un estudiante afirma: «Este texto de 14 líneas escritas seguidas, sin estrofas ni rima, es un soneto». ¿Qué falta? A) estar organizado en dos cuartetos y dos tercetos y tener rima consonante B) tener un título y estar firmado por un poeta reconocido", "A) estar organizado en dos cuartetos y dos tercetos y tener rima consonante", "Los 14 versos no bastan: la estructura y la rima definen el soneto."),
    E("Otra estudiante escribe: «Este poema alude a un texto muy antiguo, aunque no sé cuál ni dónde dice nada de eso». ¿Qué problema tiene? A) sin el texto relacionado a la vista no se puede afirmar la intertextualidad B) ninguno; basta con que el poema suene parecido a un texto antiguo", "A) sin el texto relacionado a la vista no se puede afirmar la intertextualidad", "Hay que poder citar qué se retoma y compararlo.")],
   [E("Las palabras finales de ocho versos de ejemplo son: 1 mar, 2 luz, 3 cruz, 4 soñar, 5 volar, 6 sol, 7 farol, 8 callar. ¿Qué esquema forman y cumplen el clásico ABBA ABBA? A) ABBA ACCA: no cumplen el clásico, porque el segundo cuarteto no repite las rimas del primero B) ABBA ABBA: sí lo cumplen, porque los dos cuartetos empiezan y terminan con la misma rima C) ABAB ABAB: no lo cumplen, porque las rimas se alternan en los dos cuartetos", "A) ABBA ACCA: no cumplen el clásico, porque el segundo cuarteto no repite las rimas del primero", "Mar, soñar, volar y callar riman en -ar (A); luz y cruz en -uz (B); sol y farol en -ol (C)."),
    E("Poema libre de ejemplo, de tres versos sin rima: «“Si un día no consigo decidir”, dice un verso de un soneto que leí. / Yo, hoy, decido: / me levanto y salgo a caminar.» ¿Es un soneto? A) no: no tiene la forma, pero tiene una relación intertextual con uno B) sí, porque cita un verso de un soneto y habla de un soneto", "A) no: no tiene la forma, pero tiene una relación intertextual con uno", "Citar un soneto no lo convierte en soneto: la forma depende de versos, estrofas y rima.")]),
   [E("La biblioteca exhibe dos textos sobre el mar. Texto 1: un poema de 14 versos en dos cuartetos y dos tercetos, con rima consonante. Texto 2: un poema de tres versos libres que cita un verso del primero. Para el cartel, ¿qué etiquetas son correctas? A) texto 1: soneto; texto 2: poema con relación intertextual con el soneto B) texto 1 y texto 2: sonetos, porque ambos hablan del mar y citan versos", "A) texto 1: soneto; texto 2: poema con relación intertextual con el soneto", "El primero tiene la forma del soneto; el segundo solo se relaciona con él mediante una cita.")],
  [E("¿Cómo se llaman las estrofas de cuatro versos de un soneto? A) cuartetos B) tercetos", "A) cuartetos", "Los tercetos tienen tres versos."),
   E("En muchos sonetos, ¿qué suelen hacer los tercetos? A) desarrollar la idea o cerrarla con un giro o conclusión B) repetir el primer cuarteto con otras palabras y otra rima", "A) desarrollar la idea o cerrarla con un giro o conclusión", "Así se explicó la función de los tercetos."),
   E("Para analizar una intertextualidad, ¿qué pregunta es clave? A) qué retoma el texto del otro y qué cambia B) cuántas páginas y cuántos poemas tiene el libro donde aparece", "A) qué retoma el texto del otro y qué cambia", "Se comparan lo retomado y lo transformado.")],
  (f"Lee el soneto de ejemplo: {SON} Escribe: 1) el esquema de rima de los tercetos, 2) qué plantean los cuartetos y qué hacen los tercetos, 3) dos versos propios que respondan al soneto citando uno de sus versos entre comillas.",
   "1) CDC DCD (decidir, melancolía, abrir / alegría, seguir, compañía). 2) Los cuartetos muestran lo que enseña la orilla; los tercetos pasan al hablante y concluyen que esperar es seguir. 3) «“Esperar es seguir”, dice el soneto; / yo aprendo que seguir también es contar las olas.»",
   ["identifica correctamente la rima de los tercetos", "relaciona forma y sentido", "cita un verso del soneto en su respuesta"], ["tres respuestas en el cuaderno"], ["nombrar la rima sin explicar el sentido", "citar un verso que no está en el soneto"],
   "Comprueba que los versos citados estén en el soneto y que las palabras finales de tus tercetos coincidan con tu esquema."),
  "Anota dos pares de palabras que rimen en consonante y dos que no, y explica la diferencia.",
  "Escribe un cuarteto con esquema ABBA sobre un lugar que conozcas.")

# ------------------------------------------------------------------ OA 04 · clase 6
PP = "«El pan de ayer sigue en la mesa, / duro como una promesa vieja. / Mi abuela lo ablanda con leche tibia / y dice que nada se bota si alguien lo espera.»"

L(OA4, 6,
  "Aprenderé a formular una lectura propia de un poema, combinando hablante, símbolo, recursos y relación fragmento-total, y a defenderla con evidencias.",
  ["Interpreto símbolos y recursos con evidencias.", "Contrasto dos lecturas de un mismo poema."],
  ["Una lectura propia es una interpretación del poema completo que tú formulas y defiendes con el texto. No es un resumen ni una lista de figuras: es una afirmación sobre lo que el poema dice y cómo lo dice. Una fórmula útil es «El poema sugiere que… porque…» o «Puede leerse como…», seguida de dos o tres evidencias.",
   "Una lectura propia sólida combina aspectos de la clase anterior: la actitud del hablante hacia el tema, el símbolo central, un recurso (lenguaje figurado o repetición) con su efecto y la relación entre un fragmento clave y el total, como el giro del cierre. No hace falta nombrarlos todos: se eligen los que mejor sostienen tu idea. Cada evidencia se cita brevemente entre comillas y se explica con tus palabras.",
   "La lectura propia usa verbos prudentes («sugiere», «permite leer», «puede interpretarse») porque otras lecturas son posibles, pero esa prudencia no reemplaza las pruebas. Al hablar de la voz del poema se dice «el hablante», no «el autor». Al terminar, comprueba tres cosas: ¿mi idea explica el poema completo?, ¿cada evidencia viene del texto?, ¿expliqué el efecto de los recursos?"],
  [("lectura propia", "interpretación del poema completo, formulada por quien lee y defendida con el texto"), ("evidencia", "verso o palabra del poema que respalda una idea"), ("verbo prudente", "verbo que presenta una interpretación como posible, como «sugiere» o «puede leerse»"), ("síntesis", "idea que reúne varios aspectos en una sola afirmación")],
  [("Escribir una lectura propia", f"Poema de ejemplo: {PP} Formula una lectura propia.",
    ["Actitud: el hablante mira a su abuela con respeto; el tema es cuidar lo que parece viejo.", "Símbolo y recurso: el pan duro representa lo antiguo que parece inservible, y la comparación «duro como una promesa vieja» lo une con compromisos que aún valen.", "Total: el último verso da el sentido: nada se descarta si alguien lo espera."],
    "El poema sugiere que cuidar lo viejo es una forma de cariño, porque la abuela ablanda el pan «con leche tibia» y afirma que «nada se bota si alguien lo espera»; la comparación «duro como una promesa vieja» liga el pan con compromisos antiguos que todavía valen"),
   ("Mejorar una lectura floja", f"Con ese mismo poema, {PP} un estudiante escribe: «El poema habla de pan y de una abuela. Es muy bonito.» ¿Qué le falta y cómo lo mejoras?",
    ["Solo resume y opina: no interpreta ni cita versos.", "Agrego una idea («sugiere que…»), una evidencia entre comillas y su explicación.", "Reescribo: «El poema sugiere que la abuela valora lo cotidiano, pues dice que “nada se bota si alguien lo espera”.»"],
    "Le falta una idea interpretativa y evidencias; mejorada: «El poema sugiere que la abuela valora lo cotidiano, pues dice que “nada se bota si alguien lo espera”»")],
  [("Escribir un resumen del poema («cuenta que una abuela ablanda el pan») y llamarlo lectura.", "Un resumen dice qué pasa, pero no interpreta qué sugiere.", "Agrega «sugiere que… porque…» y una evidencia."),
   ("Escribir «el autor vivió esto con su abuela».", "Se confunde al autor con el hablante y se afirma lo que el poema no demuestra.", "Habla del hablante y apóyate solo en el texto.")],
  ([E("¿Qué es una lectura propia de un poema? A) una interpretación del poema completo defendida con evidencias B) un resumen de lo que ocurre en cada estrofa, con un comentario final", "A) una interpretación del poema completo defendida con evidencias", "No basta contar lo que pasa; hay que sostener un sentido con el texto."),
    E("¿Cuál es una forma prudente de presentar una lectura? A) «El poema sugiere que…» B) «El poema dice la única verdad: que…»", "A) «El poema sugiere que…»", "Los verbos prudentes reconocen que puede haber otras lecturas."),
    E("¿Cómo se incluye una evidencia en la lectura? A) citando brevemente el verso entre comillas y explicándolo B) copiando el poema completo para que no falte ningún verso", "A) citando brevemente el verso entre comillas y explicándolo", "La cita breve prueba la idea y la explicación muestra por qué.")],
   [E("Poema de ejemplo: «Mi padre arregla el farol de la esquina / y no pregunta quién pagará la luz. / Sube la escalera como quien conoce / el peso exacto de volver a encender.» ¿Cuál es una lectura propia? A) «El poema sugiere que ayudar sin esperar pago es una forma de cuidar al barrio, porque el padre arregla el farol “sin preguntar quién pagará la luz”» B) «El poema cuenta que un padre sube una escalera para arreglar el farol de la esquina y que no pregunta quién pagará la luz» C) «El poema es bonito porque habla de un padre trabajador y generoso que arregla el farol del barrio y lo hace con alegría»", "A) «El poema sugiere que ayudar sin esperar pago es una forma de cuidar al barrio, porque el padre arregla el farol “sin preguntar quién pagará la luz”»", "Es la única que formula una idea sobre el sentido y la prueba con un verso."),
    E("En una lectura propia, ¿qué aspectos conviene combinar? A) la actitud del hablante, el símbolo, un recurso con su efecto y la relación entre un fragmento y el total B) la biografía del autor, el año de publicación y lo que opinan los críticos del libro", "A) la actitud del hablante, el símbolo, un recurso con su efecto y la relación entre un fragmento y el total", "Son los aspectos que se analizan en el poema; los datos externos no prueban nada del texto."),
    E("¿Qué expresión deja abierta la posibilidad de otras lecturas? A) «puede interpretarse como» B) «es seguro que el poema dice»", "A) «puede interpretarse como»", "El verbo prudente reconoce que el poema admite más de una lectura.")],
   [E("Poema de ejemplo: «Hoy cuento mis pasos hasta la parada: / veintidós, como siempre. / La lluvia no cambia el número, / pero sí el peso de cada uno.» ¿Cuál es la mejor lectura propia? A) «El poema sugiere que una rutina idéntica puede sentirse distinta según el ánimo, pues los pasos siguen siendo veintidós, pero la lluvia cambia “el peso de cada uno”» B) «El poema muestra que el hablante cuenta sus pasos hasta la parada, veintidós como siempre, aunque llueva» C) «El poema es triste porque llueve, y por eso el hablante camina con más lentitud hacia la parada»", "A) «El poema sugiere que una rutina idéntica puede sentirse distinta según el ánimo, pues los pasos siguen siendo veintidós, pero la lluvia cambia “el peso de cada uno”»", "Formula una idea y la apoya con dos versos; las otras solo resumen o afirman sin prueba."),
    E("Poema de ejemplo: «Mi hermana guarda sus dibujos en una caja / y la caja guarda a mi hermana. / Cuando la abre, huele a lápiz y a casa, / y se hace pequeña y se hace grande.» Lectura: «La caja simboliza la memoria que protege a quien la abre». ¿Qué evidencia la sostiene mejor? A) «la caja guarda a mi hermana» y «se hace pequeña y se hace grande» B) «guarda sus dibujos en una caja», porque nombra el objeto del poema", "A) «la caja guarda a mi hermana» y «se hace pequeña y se hace grande»", "Muestran que la caja protege y transforma a quien la abre; el otro verso solo describe un objeto."),
    E("Una lectura de un poema dice solamente: «Hay una anáfora de “hoy” y una personificación de la calle». ¿Qué paso le falta? A) explicar el efecto de esos recursos y relacionarlo con la idea central B) agregar más figuras, como una metáfora y una comparación, sin explicarlas", "A) explicar el efecto de esos recursos y relacionarlo con la idea central", "Nombrar recursos no basta; se debe explicar qué aportan al sentido.")],
   [E("Poema de ejemplo: «No hay cerco en el jardín de mi tía. / Los vecinos cruzan, cortan una flor, / dejan un tomate en la puerta. / Ella dice que lo que no se encierra / no se pierde: se reparte.» Lectura 1: el jardín sin cerco simboliza una forma de vivir en comunidad donde compartir evita perder. Lectura 2: la tía es descuidada y por eso le cortan flores. ¿Cuál tiene mejor respaldo? A) la 1, por «dejan un tomate en la puerta» y «se reparte» B) la 2, por «cortan una flor» y por «no hay cerco en el jardín»", "A) la 1, por «dejan un tomate en la puerta» y «se reparte»", "Esos versos muestran intercambio y reparto; la tía misma explica su actitud, que no es descuido."),
    E("Un estudiante escribe: «Esto significa que el autor tuvo una tía generosa». ¿Qué debe corregir? A) hablar del hablante y no afirmar la biografía del autor B) agregar la fecha de nacimiento del autor y su lugar de residencia", "A) hablar del hablante y no afirmar la biografía del autor", "El poema no demuestra qué vivió el autor; solo muestra lo que dice el hablante.")],
   [E("Poema de ejemplo: «La radio de mi padre sigue en el estante. / Nadie la enciende, pero a veces / la casa se queda quieta / como esperando que alguien diga: “buenas tardes”.» ¿Cuál lectura integra mejor símbolo, recurso y actitud? A) «La radio apagada simboliza la ausencia de la voz del padre, y la comparación “como esperando que alguien diga buenas tardes” muestra que la casa conserva esa espera; el hablante lo mira con ternura» B) «El poema habla de una radio que está en el estante de la casa de un padre y que nadie enciende, aunque a veces la casa se queda quieta» C) «El poema trata de los electrodomésticos que se apagan en las casas y de lo silenciosas que se vuelven cuando nadie los usa nunca»", "A) «La radio apagada simboliza la ausencia de la voz del padre, y la comparación “como esperando que alguien diga buenas tardes” muestra que la casa conserva esa espera; el hablante lo mira con ternura»", "Combina el símbolo, la comparación y la actitud con versos del poema."),
    E("Poema de ejemplo: «Espero el bus con el termo en la mano. / Espero tranquilo, sin mirar el reloj. / Espero, y el frío me enseña a respirar.» Para sostener la idea «el hablante vive la espera con calma», ¿qué evidencia es más decisiva? A) «sin mirar el reloj» y la repetición de «espero», que da un ritmo pausado B) «con el termo en la mano», porque nombra un objeto que acompaña al hablante en la espera", "A) «sin mirar el reloj» y la repetición de «espero», que da un ritmo pausado", "Muestran ausencia de apuro; nombrar el termo no prueba la calma.")]),
   [E("El concurso de lectura del liceo pide: una idea central, una evidencia citada y un recurso con su efecto. Poema de ejemplo: «La escalera del patio tiene un peldaño suelto. / Todos lo pisan con cuidado, / como quien camina sobre un secreto. / Nadie lo arregla: sirve para recordarnos.» Lectura de una compañera: «El poema sugiere que un defecto compartido une a la comunidad, porque “nadie lo arregla” y todos lo pisan “con cuidado”». ¿Qué le falta? A) un recurso con su efecto, como la comparación «como quien camina sobre un secreto» B) una segunda idea central que contradiga a la primera, para mostrar otra lectura", "A) un recurso con su efecto, como la comparación «como quien camina sobre un secreto»", "Tiene idea central y evidencia, pero no menciona ningún recurso ni su efecto.")],
  [E("¿Qué diferencia hay entre una lectura propia y un resumen? A) la lectura propia interpreta el sentido y lo prueba con versos; el resumen solo cuenta qué pasa B) el resumen es una interpretación y la lectura propia solo cuenta lo que pasa", "A) la lectura propia interpreta el sentido y lo prueba con versos; el resumen solo cuenta qué pasa", "La interpretación y las pruebas distinguen la lectura propia."),
   E("Al terminar una lectura propia, ¿qué conviene comprobar? A) que la idea explique el poema completo y que las evidencias vengan del texto B) que sea más larga y que use palabras más difíciles que la de los demás", "A) que la idea explique el poema completo y que las evidencias vengan del texto", "Son las comprobaciones que se enseñaron en la clase."),
   E("¿Qué verbo es más adecuado para presentar una lectura? A) sugiere B) demuestra de forma definitiva", "A) sugiere", "Los verbos prudentes reconocen otras lecturas posibles.")],
  ("Lee este poema de ejemplo: «La olla de mi madre no cabe en el estante. / La dejamos en la mesa, abierta al día. / Cada visita se sirve sin pedir permiso / y se va con un pedazo de la tarde.» Escribe una lectura propia de cuatro o cinco oraciones que incluya: una idea central con un verbo prudente, dos evidencias citadas, un recurso o símbolo con su efecto y la actitud del hablante.",
   "El poema sugiere que la olla simboliza la hospitalidad de una casa abierta a todos. La evidencia es que la olla está «abierta al día» y que «cada visita se sirve sin pedir permiso». La expresión «se va con un pedazo de la tarde» es una metáfora que muestra que lo compartido deja algo valioso a quien se va. El hablante mira esta costumbre con orgullo y ternura, y la presenta como algo natural en su casa.",
   ["formula una idea central con verbo prudente", "cita dos versos como evidencia", "explica el efecto de un recurso o símbolo", "señala la actitud del hablante"], ["párrafo de cuatro o cinco oraciones"], ["resumir sin interpretar", "citar versos sin explicarlos", "hablar de la vida del autor"],
   "Subraya la idea central, las dos citas y el efecto del recurso; comprueba que estén los cuatro elementos."),
  "Escribe una lectura propia de tres oraciones de una letra de canción o poema que conozcas, sin copiar el texto.",
  "Escribe dos lecturas propias del mismo poema con ideas distintas y explica cuál tiene más evidencias.")

# ------------------------------------------------------------------ OA 04 · clase 7
L(OA4, 7,
  "Aprenderé a revisar una interpretación con una lista de criterios y a transferir lo aprendido sobre poesía (voz, símbolo, recursos, forma y relaciones) a un poema nuevo.",
  ["Formulo una lectura propia con evidencias.", "Reconozco la estructura del soneto y la intertextualidad."],
  ["Revisar una interpretación es volver sobre ella con preguntas. Una lista de revisión útil: 1) ¿identifica al hablante y su actitud hacia el tema?, 2) ¿interpreta el símbolo con versos?, 3) ¿explica el efecto de los recursos?, 4) ¿relaciona fragmentos con el total?, 5) ¿considera la forma (por ejemplo, la estructura del soneto) y las relaciones con otros textos cuando son pertinentes? No todo poema pide todos los puntos: se usan los que ayudan.",
   "Al revisar se buscan tres tipos de fallas: afirmaciones sin evidencia, evidencias que no prueban la idea y versos importantes ignorados. Se corrigen agregando una cita, reemplazando la evidencia o ajustando la idea para que explique más versos. Tras la revisión puedes mantener tu lectura, con mejores pruebas, o cambiarla; ambas decisiones son válidas si las explicas con el texto.",
   "Transferir es usar lo aprendido en un poema distinto: otro hablante, otra forma, otro tema. El procedimiento es el mismo: leer con un propósito, localizar evidencias, analizar recursos, contrastar lecturas, situar el texto y formular tu lectura. Un lector autónomo ajusta el procedimiento al poema: un soneto pide mirar su estructura y un poema que cita a otro texto pide mirar la intertextualidad."],
  [("revisión", "relectura de una interpretación con criterios para mejorarla"), ("lista de revisión", "conjunto de preguntas para comprobar una interpretación"), ("falla", "defecto de una interpretación, como una afirmación sin evidencia"), ("transferir", "aplicar lo aprendido a un poema distinto")],
  [("Revisar una lectura floja", "Poema de ejemplo: «Mi mamá planta cilantro en una lata. / Dice que el balcón también es campo. / Riega con el agua del mate frío / y espera, sin apuro, las hojas.» Lectura floja: «El poema trata de plantas y de una mamá. Es bonito.» Revísala con la lista de la clase.",
    ["Punto 1: no dice la actitud del hablante hacia el tema.", "Puntos 2 y 3: no cita versos ni explica ningún recurso.", "Reescribo: idea («sugiere que…»), una cita y su efecto."],
    "Versión mejorada: «El poema sugiere que la madre convierte un espacio pequeño en un lugar de cuidado, porque llama “campo” al balcón; el verbo “espera, sin apuro” muestra paciencia, y el hablante la mira con ternura.»"),
   ("Decidir qué criterios aplican a un poema nuevo", "Poema de ejemplo: «“Ten paciencia”, me dijo la abuela, / y puso a hervir el agua del té. / Yo, con ese consejo a cuestas, / aprendí a mirar el vapor.» ¿Qué puntos de la lista aplican?",
    ["Punto 1 (hablante y actitud): sí, el hablante recuerda un consejo con aprecio.", "Puntos 3 y 4: sí, «consejo a cuestas» es una metáfora y el último verso cierra el sentido.", "Punto 5: no hay soneto, y «ten paciencia» es un consejo oral, no un texto identificable."],
    "Aplican los puntos 1, 3 y 4; no aplica la forma de soneto ni la intertextualidad")],
  [("Revisar solo la ortografía y creer que se revisó la interpretación.", "Se corrige la forma de escribir, pero no las evidencias ni la idea.", "Después de la ortografía, aplica la lista de revisión al contenido."),
   ("Mantener una lectura aunque haya versos importantes sin explicar.", "Una lectura que ignora versos clave es frágil.", "Agrega esos versos a tu explicación o ajusta tu idea.")],
  ([E("¿Para qué sirve una lista de revisión? A) para comprobar si la interpretación cumple criterios y mejorarla B) para reemplazar la lectura del poema por un resumen de los versos", "A) para comprobar si la interpretación cumple criterios y mejorarla", "Es una herramienta de relectura, no sustituye al poema."),
    E("¿Cuál es una falla frecuente en una interpretación? A) una afirmación sin evidencia B) una cita breve que se explica", "A) una afirmación sin evidencia", "La cita explicada es una virtud; la afirmación sin prueba es una falla."),
    E("Transferir lo aprendido significa… A) aplicarlo a un poema distinto B) copiar un poema leído antes", "A) aplicarlo a un poema distinto", "Se trata de usar el procedimiento con otro hablante, forma o tema.")],
   [E("Poema de ejemplo: «El perro del vecino me espera en la reja / y mueve la cola como quien aplaude. / Lo saludo por su nombre, que invento cada día.» Una lectura dice: «El poema muestra un vínculo afectuoso». ¿Qué falla tiene? A) no cita versos que la prueben B) cita demasiados versos", "A) no cita versos que la prueben", "Es una afirmación sin evidencia; faltan citas como «lo saludo por su nombre»."),
    E("Con el poema del perro del vecino, para probar que «el hablante se divierte con el perro», ¿qué cita es más sólida? A) «lo saludo por su nombre, que invento cada día» B) «el perro del vecino me espera en la reja»", "A) «lo saludo por su nombre, que invento cada día»", "Muestra un juego diario; la otra cita solo menciona al perro."),
    E("En la revisión de una lectura de un soneto no se miró cómo se organizan sus estrofas. ¿Qué punto de la lista no se cumplió? A) el de la forma B) el del hablante", "A) el de la forma", "El punto 5 de la lista incluye la estructura del soneto.")],
   [E("Poema de ejemplo: «Cada tarde dejo mi taza al sol / y la taza se llena de una luz amarilla. / No tomo nada: la sostengo un rato / como se sostiene un buen día.» Lectura floja: «El poema habla de una taza.» ¿Qué revisión es mejor? A) «El poema sugiere que el hablante valora los momentos simples: sostiene la taza llena de luz “como se sostiene un buen día”, y esa comparación muestra que la calma es lo que se bebe» B) «El poema habla de una taza que el hablante deja al sol cada tarde y que se llena de una luz amarilla muy bonita» C) «La taza simboliza la tristeza del hablante, porque no toma nada y se queda sosteniéndola un rato sin hacer más»", "A) «El poema sugiere que el hablante valora los momentos simples: sostiene la taza llena de luz “como se sostiene un buen día”, y esa comparación muestra que la calma es lo que se bebe»", "Agrega idea, cita y efecto de una comparación; las otras no interpretan o no tienen evidencia."),
    E("Poema de ejemplo: «Guardé el mar en un frasco / para verlo cuando quisiera. / Pero el frasco solo tenía agua, / y el mar seguía afuera.» Una lectura dice: «El mar simboliza la libertad, porque se menciona en el primer y en el último verso». ¿Qué falla tiene la evidencia? A) solo muestra que el mar se menciona, no que simbolice libertad B) ninguna: mencionar el mar en dos versos basta para probar que simboliza libertad", "A) solo muestra que el mar se menciona, no que simbolice libertad", "Una buena evidencia usa versos como «el mar seguía afuera», que sugieren lo que no se puede encerrar."),
    E("Te entregan un poema de 14 versos en dos cuartetos y dos tercetos, con rima consonante. Además del hablante y de los recursos, ¿qué aspecto conviene analizar? A) la estructura del soneto y qué hacen los cuartetos y los tercetos B) solo el número de palabras y de versos que tiene cada estrofa", "A) la estructura del soneto y qué hacen los cuartetos y los tercetos", "La forma aporta al sentido, como se vio en la clase del soneto.")],
   [E("Dos estudiantes revisan sus lecturas. La primera cambia su idea al ver un verso ignorado y explica por qué. El segundo mantiene su idea, pero agrega dos citas que la prueban. ¿Qué decisión es válida? A) ambas, si explican su decisión con el texto B) solo la de quien mantiene su lectura", "A) ambas, si explican su decisión con el texto", "Se puede mantener o cambiar la lectura cuando hay razones tomadas del poema."),
    E("Una revisión corrigió solo tildes y comas de una interpretación. ¿Revisó la interpretación? A) no: revisó la escritura, pero no las evidencias ni la idea B) sí, porque corregir tildes y comas también mejora la interpretación", "A) no: revisó la escritura, pero no las evidencias ni la idea", "La revisión de la interpretación mira idea, evidencias y versos ignorados.")],
   [E("Poema de ejemplo: «Mi tío ata un hilo rojo al poste de la esquina / y lo suelta cuando pasa el viento. / Dice que así le habla a mi tía, / que vive lejos, donde no hay postes.» Lectura: «El poema trata de la soledad. El hilo simboliza la soledad. Es un poema muy triste.» ¿Cuál es el mejor diagnóstico? A) ignora que el hilo es un modo de comunicarse con la tía lejana y afirma tristeza sin evidencia B) no tiene fallas, porque nombra el tema y el símbolo del poema con claridad C) su única falla es ser demasiado corta; con más oraciones quedaría completa", "A) ignora que el hilo es un modo de comunicarse con la tía lejana y afirma tristeza sin evidencia", "Los dos últimos versos muestran comunicación a distancia, no solo soledad."),
    E("Poema de ejemplo: «“Si un día no consigo decidir”, dice un verso de un soneto que leí. / Yo, hoy, decido: me levanto y salgo a caminar.» ¿Qué análisis corresponde hacer? A) comparar qué retoma del verso citado y qué cambia: la duda pasa a ser decisión B) contar las sílabas del verso citado y comprobar si el poema es un soneto", "A) comparar qué retoma del verso citado y qué cambia: la duda pasa a ser decisión", "Es una intertextualidad: se cita y se transforma el sentido del verso.")]),
   [E("Revisas la lectura de un compañero con tres criterios: idea central, una evidencia citada y el efecto de un recurso. Poema de ejemplo: «Mi abuelo teje sin prisa el chaleco de invierno, / mueve la lana como quien ordena el tiempo. / Yo lo miro y aprendo que la espera / también tiene un oficio.» Lectura: «El poema sugiere que la paciencia se aprende mirando a los mayores, porque el hablante contempla a su abuelo tejiendo “sin prisa”». ¿Qué criterio falta? A) el efecto de un recurso, como la comparación «como quien ordena el tiempo» B) la idea central, que no se formula con claridad en la lectura", "A) el efecto de un recurso, como la comparación «como quien ordena el tiempo»", "Tiene idea central y evidencia, pero no analiza ningún recurso.")],
  [E("Al revisar una interpretación, ¿qué se corrige? A) afirmaciones sin prueba, evidencias que no sirven y versos ignorados B) solo la letra, los márgenes y la presentación del trabajo", "A) afirmaciones sin prueba, evidencias que no sirven y versos ignorados", "Son las tres fallas que se buscan en la revisión."),
   E("Después de revisar, ¿es válido cambiar de lectura? A) sí, si se explica con el texto B) no, porque cambiar muestra que la primera lectura era mala", "A) sí, si se explica con el texto", "Cambiar con razones forma parte de leer con precisión."),
   E("Si el poema que lees tiene una cita de otro texto, ¿qué debes agregar a tu análisis? A) la intertextualidad: qué se retoma y qué cambia B) el número de páginas y el precio del libro del poema", "A) la intertextualidad: qué se retoma y qué cambia", "El procedimiento se ajusta a las características del poema.")],
  ("Lee este poema de ejemplo y esta lectura floja. Poema: «Bajo la lluvia de marzo, / mi hermano abre un paraguas roto / y camina de lado, / con la mitad del cielo sobre el hombro.» Lectura floja: «El poema es sobre un paraguas y un hermano. Me gustó mucho.» Con la lista de revisión de la clase, escribe: 1) dos fallas de esa lectura, 2) una lectura mejorada de tres oraciones con idea, evidencia y efecto de un recurso, 3) qué cambió en tu forma de leer el poema.",
   "1) No interpreta (solo resume y opina) y no cita ningún verso. 2) El poema sugiere que el hermano enfrenta una dificultad con humor y paciencia, pues abre un paraguas roto y camina «de lado». La metáfora «la mitad del cielo sobre el hombro» muestra que carga solo una parte del peso porque el paraguas lo protege a medias. El hablante lo mira con ternura. 3) Pasé de resumir a explicar qué sugiere el poema y a probarlo con versos.",
   ["identifica dos fallas reales", "escribe una lectura con idea, evidencia y efecto", "reflexiona sobre su cambio de lectura"], ["tres respuestas en el cuaderno"], ["repetir la lectura floja con otras palabras", "mejorar sin citar versos"],
   "Aplica a tu lectura mejorada los cinco puntos de la lista de la clase y marca cuáles cumple."),
  "Toma una interpretación que hayas escrito antes y revísala con la lista de la clase; anota un cambio concreto.",
  "Escribe un poema breve que cite un verso del soneto «La orilla» de la clase anterior y explica qué retomas y qué cambias.")

# ------------------------------------------------------------------ OA 05 · clase 1
EA = "«(Patio trasero, al atardecer. Un cerco de madera con una tabla suelta. ROSA riega una planta; HUGO aparece al otro lado.) HUGO.—Esa tabla la rompió su perro. ROSA.—(Sin mirarlo.) Mi perro lleva dos años muerto. HUGO.—(Baja la voz.) Entonces la rompió el invierno... pero igual hay que arreglarla. ROSA.—Arréglela usted. Yo ya no pido permiso para cruzar.»"
ES3 = "«(Plaza de un pueblo, mediodía. DON ELÍAS vende frutas; su hija MAITE sostiene una carta.) MAITE.—Me aceptaron en la universidad de la capital. ELÍAS.—(Sin mirarla.) Alguien tiene que ayudarme en el puesto. MAITE.—Siempre es alguien, papá, y siempre soy yo. ELÍAS.—(Ordena las frutas con prisa.) Cuando yo tenía tu edad, nadie me preguntó qué quería.»"

L(OA5, 1,
  "Aprenderé a leer un texto dramático con un propósito: distinguir el texto de su representación y reconocer el conflicto y el problema humano que expresa.",
  ["Distingo diálogo y narración.", "Sé qué es un personaje y qué quiere."],
  ["Un texto dramático es un texto escrito para ser representado ante un público. Está formado por diálogos (lo que dicen los personajes, marcados con su nombre), monólogos (cuando un personaje habla solo en voz alta para expresar lo que piensa o siente) y acotaciones (indicaciones del autor, entre paréntesis, sobre gestos, movimientos, lugar, luz o sonido). La representación es la obra puesta en escena con actores; no es lo mismo que el texto: dos representaciones del mismo texto pueden ser muy distintas.",
   "El conflicto es la oposición entre fuerzas que mueve la acción: dos personajes que quieren cosas incompatibles, un personaje contra una norma o contra sí mismo. Detrás del conflicto hay un problema humano, una dificultad que podría afectar a cualquier persona, como el orgullo que impide reconciliarse, el miedo a decir la verdad o la tensión entre el deber y el deseo. El conflicto es concreto (la disputa por un cerco); el problema humano es más amplio (la dificultad de reconciliarse).",
   "Para entrar a una escena con propósito, formula una pregunta: ¿qué quiere cada personaje y qué se lo impide? Busca pistas en los diálogos y en las acotaciones. Luego escribe dos oraciones: el conflicto («Rosa y Hugo discuten por un cerco») y el problema humano que expresa («la dificultad de hablar después de una distancia»). Evita contar la escena entera: lo que importa es qué enfrenta a los personajes y por qué."],
  [("texto dramático", "texto escrito para ser representado ante un público"), ("acotación", "indicación del autor sobre gestos, lugar, luz o sonido, escrita entre paréntesis"), ("monólogo", "momento en que un personaje habla solo en voz alta para expresar lo que piensa o siente"), ("conflicto", "oposición entre fuerzas que mueve la acción"), ("problema humano", "dificultad amplia que podría afectar a cualquiera"), ("representación", "obra puesta en escena con actores")],
  [("Distinguir acotaciones y diálogos", f"Escena de ejemplo: {EA} ¿Qué muestran las acotaciones «(Sin mirarlo.)» y «(Baja la voz.)»?",
    ["Las acotaciones están entre paréntesis y no las dice nadie en voz alta.", "«(Sin mirarlo.)» indica que Rosa evita el contacto; «(Baja la voz.)» muestra que Hugo suaviza el tono.", "Así, las acotaciones muestran la actitud de cada uno que los diálogos no dicen."],
    "Rosa evita mirar a Hugo y Hugo suaviza el tono: las acotaciones revelan sus actitudes"),
   ("Conflicto y problema humano", f"Con la misma escena, {EA} ¿Cuál es el conflicto y cuál el problema humano?",
    ["Pregunto qué quiere cada uno: Hugo quiere que se arregle la tabla; Rosa responde con distancia.", "El conflicto concreto es la discusión por la tabla rota del cerco; «ya no pido permiso para cruzar» sugiere que antes se llevaban bien.", "Detrás hay una dificultad más amplia: reconciliarse después de una distancia."],
    "Conflicto: Hugo y Rosa discuten por la tabla rota del cerco. Problema humano: la dificultad de reconciliarse")],
  [("Contar toda la escena como si fuera el conflicto.", "El conflicto es la oposición central, no un resumen de lo que ocurre.", "Pregunta qué quiere cada personaje y qué se lo impide."),
   ("Confundir el texto con la representación («en la obra, la luz era roja» como si fuera el texto).", "El texto trae diálogos y acotaciones; la puesta en escena decide cómo se cumplen.", "Aclara si hablas de lo escrito o de lo que se vio en el escenario.")],
  ([E("¿Qué es una acotación? A) una indicación del autor sobre gestos, lugar, luz o sonido B) lo que dicen los actores en voz alta durante la representación", "A) una indicación del autor sobre gestos, lugar, luz o sonido", "Se escribe entre paréntesis y no la pronuncia ningún personaje."),
    E("Un personaje habla solo, en voz alta, para expresar lo que siente. ¿Cómo se llama esa parte del texto? A) monólogo B) diálogo", "A) monólogo", "El diálogo es entre dos o más personajes; en el monólogo habla uno solo."),
    E("¿Cuál opción describe una representación? A) la obra puesta en escena con actores B) el texto escrito con diálogos y acotaciones", "A) la obra puesta en escena con actores", "La representación es lo que se ve y se oye en el escenario; lo escrito es el texto.")],
   [E("Escena de ejemplo: «(Sala de ensayo del liceo. NICOLÁS sostiene un guion; VALERIA lo mira desde la puerta.) NICOLÁS.—Te dije que el papel de la reina era mío. VALERIA.—Y la profesora dijo que decidía el curso. NICOLÁS.—(Cierra el guion de golpe.) Pregunta a todos por qué te prefieren.» ¿Cuál es el conflicto? A) Nicolás y Valeria disputan quién hará el papel de la reina B) Nicolás y Valeria disputan quién cerrará el guion al terminar el ensayo", "A) Nicolás y Valeria disputan quién hará el papel de la reina", "Ambos quieren el mismo papel: es una oposición entre deseos incompatibles."),
    E("Escena de ejemplo: «(Un andén vacío. SOFÍA, sola, con una maleta, mira el reloj.) SOFÍA.—(Para sí.) Si subo, no vuelvo. Si me quedo, se enterarán de que tuve miedo. Y yo ya no sé qué quiero.» ¿Qué es la intervención de Sofía? A) un monólogo que muestra un conflicto interior B) un diálogo, porque expresa dos ideas opuestas en la misma frase", "A) un monólogo que muestra un conflicto interior", "Habla sola en voz alta y expresa su duda; la acotación «para sí» lo confirma."),
    E("En «MARTA.—(Abre la ventana.) Hace calor.», ¿cuál es la acotación? A) «(Abre la ventana.)» B) «Hace calor.»", "A) «(Abre la ventana.)»", "Está entre paréntesis y describe una acción; «Hace calor» lo dice el personaje.")],
   [E(f"Escena de ejemplo: {ES3} ¿Qué problema humano expresa? A) la tensión entre el deber con la familia y el deseo de seguir el propio camino B) la dificultad de vender frutas en una plaza cuando hay mucha competencia", "A) la tensión entre el deber con la familia y el deseo de seguir el propio camino", "Maite quiere estudiar y su padre le pide ayudar en el puesto; la dificultad es más amplia que la venta de frutas."),
    E(f"Con la escena de la plaza, {ES3} ¿cuál es el conflicto concreto? A) Maite quiere ir a estudiar y su padre quiere que lo ayude en el puesto B) Maite y su padre discuten por el precio de las frutas que venden en la plaza", "A) Maite quiere ir a estudiar y su padre quiere que lo ayude en el puesto", "Es la oposición entre dos deseos que aparece en el diálogo."),
    E("En la escena de la plaza (Maite quiere estudiar en la capital y Elías le pide ayuda en el puesto), las acotaciones «(Sin mirarla.)» y «(Ordena las frutas con prisa.)» muestran que Elías… A) evita enfrentar el tema B) está de buen humor", "A) evita enfrentar el tema", "No la mira y se ocupa en otra cosa: esquiva la conversación.")],
   [E("Un estudiante dice: «La obra que vimos fue igual al texto que leímos». Su profesora explica que el director cortó una escena y cambió el final. ¿Qué muestra eso? A) que la representación es una versión del texto, con decisiones del equipo B) que el texto cambia solo cada vez que se lee en voz alta ante un público", "A) que la representación es una versión del texto, con decisiones del equipo", "El texto queda escrito; la puesta en escena lo interpreta y puede modificarlo."),
    E("En una escena de ejemplo, dos vecinos, Rosa y Hugo, discuten por quién arregla una tabla rota del cerco, y se nota que antes se llevaban bien. Estudiante 1: «El problema humano es que pelean por una tabla». Estudiante 2: «El problema humano es la dificultad de reconciliarse tras una distancia». ¿Quién distingue mejor conflicto y problema humano? A) el estudiante 2, porque nombra una dificultad general; el 1 describe el conflicto concreto B) el estudiante 1, porque es más concreto y se apoya en un hecho de la escena", "A) el estudiante 2, porque nombra una dificultad general; el 1 describe el conflicto concreto", "El problema humano es la dificultad amplia que está detrás de la disputa concreta.")],
   [E("Escena de ejemplo: «(Una oficina pequeña. LUIS tiene un informe con errores. Su jefa, ANDREA, espera en la puerta.) LUIS.—(Para sí.) Si lo digo, me culpan. Si lo callo, otro pagará el error. (A ANDREA, con calma.) Todo en orden.» ¿Qué problema humano plantea? A) el miedo a las consecuencias frente al deber de decir la verdad B) la falta de materiales de oficina para corregir el informe a tiempo", "A) el miedo a las consecuencias frente al deber de decir la verdad", "El monólogo muestra su duda entre protegerse y avisar del error."),
    E("En un texto aparece la acotación «(Llueve.)». Un grupo teatral decide mostrar la lluvia con un sonido, sin agua en el escenario. ¿Qué muestra esa decisión? A) que la representación interpreta el texto con decisiones propias B) que el texto está equivocado y el equipo teatral lo corrige", "A) que la representación interpreta el texto con decisiones propias", "Una misma acotación puede cumplirse de varias maneras en el escenario.")]),
   [E("Vas a ver una obra del liceo y tu profesor pide anotar el conflicto de la primera escena. En ella, los hermanos Pablo e Inés discuten porque Pablo vendió, sin avisar, la bicicleta que compartían. ¿Qué anotas? A) Pablo e Inés disputan por la venta de la bicicleta compartida B) Pablo e Inés viven en la misma casa y comparten una bicicleta", "A) Pablo e Inés disputan por la venta de la bicicleta compartida", "El conflicto es la oposición entre ambos; vivir juntos es solo un dato de contexto.")],
  [E("¿En qué se diferencian un diálogo y un monólogo? A) en el diálogo hablan dos o más personajes; en el monólogo, uno solo en voz alta B) el diálogo es siempre más largo y el monólogo es siempre más breve", "A) en el diálogo hablan dos o más personajes; en el monólogo, uno solo en voz alta", "La diferencia está en quién habla, no en la extensión."),
   E("¿Qué pregunta ayuda a entrar a una escena con propósito? A) ¿qué quiere cada personaje y qué se lo impide? B) ¿cuántos actores harían falta para representar la escena?", "A) ¿qué quiere cada personaje y qué se lo impide?", "Esa pregunta lleva al conflicto, que mueve la acción."),
   E("¿Qué relación hay entre conflicto y problema humano? A) el conflicto es la oposición concreta y el problema humano, la dificultad amplia que hay detrás B) son lo mismo: el problema humano es solo otro nombre del conflicto concreto", "A) el conflicto es la oposición concreta y el problema humano, la dificultad amplia que hay detrás", "Así se distinguieron en la explicación de la clase.")],
  ("Lee esta escena de ejemplo: «(Un banco de plaza, al anochecer. EMA espera con una bolsa de regalo. RAQUEL llega corriendo.) EMA.—Dijiste a las seis. RAQUEL.—(Mira el suelo.) Me quedé ayudando en la feria de mi mamá. EMA.—Es mi cumpleaños, Raquel. (Guarda la bolsa.) Pero da igual. RAQUEL.—(Muy bajo.) No da igual. Es que no sabía cómo decirte que no tengo con qué regalarte nada.» Escribe: 1) dos acotaciones y qué muestran, 2) el conflicto en una oración, 3) el problema humano en una oración, 4) una frase de diálogo que lo prueba.",
   "1) «(Mira el suelo.)» muestra vergüenza en Raquel; «(Guarda la bolsa.)» muestra que Ema se repliega, dolida. 2) Ema se siente olvidada por la tardanza de Raquel, y Raquel oculta que no pudo conseguir un regalo. 3) La vergüenza que impide decir la verdad a un amigo. 4) «No sabía cómo decirte que no tengo con qué regalarte nada».",
   ["identifica dos acotaciones y su función", "formula el conflicto", "distingue el problema humano del conflicto", "cita un diálogo como evidencia"], ["cuatro respuestas numeradas"], ["contar la escena en vez de nombrar el conflicto", "confundir conflicto y problema humano"],
   "Comprueba que tu problema humano sea más amplio que el conflicto y que la cita esté en la escena."),
  "Busca en tu casa una escena de una serie o teleserie y anota el conflicto con una oración.",
  "Escribe una escena de seis líneas con dos acotaciones y un conflicto claro entre dos personajes.")

# ------------------------------------------------------------------ OA 05 · clase 2
EB = "«(Panadería, antes de abrir. CLARA ordena panes con rapidez. TOMÁS entra con la mochila al hombro.) CLARA.—Tomás, tercera vez esta semana. (A una clienta, aparte.) Con los jóvenes no se puede. TOMÁS.—(Sin soltar la mochila.) Mi mamá está enferma, señora. Por eso cambié el turno. CLARA.—(Se detiene.) ¿Y por qué no me lo dijiste? TOMÁS.—Porque usted dijo que acá nadie viene con problemas. CLARA.—(Tras un silencio.) Mañana entras una hora más tarde. Pero me avisas.»"

L(OA5, 2,
  "Aprenderé a localizar evidencias decisivas para analizar a un personaje: lo que dice, lo que se dice de él, lo que hace, cómo reacciona y lo que piensa, su motivación, su relación con otros y su evolución.",
  ["Distingo acotaciones, diálogos y monólogos.", "Identifico el conflicto de una escena."],
  ["Un personaje se conoce por varias vías, y cada una es una evidencia: lo que dice (sus palabras), lo que se dice de él (la opinión de otros), lo que hace (sus acciones), cómo reacciona (su respuesta ante lo que ocurre) y lo que piensa (en monólogos y apartes, y a veces en las acotaciones). Un aparte son palabras que un personaje dice al público o a sí mismo sin que los demás las oigan. Una buena caracterización no se queda con una sola vía: las cruza y busca coincidencias o contradicciones entre ellas.",
   "La motivación es la razón por la que un personaje actúa: lo que quiere o necesita (reconocimiento, protección, justicia, libertad) y lo que teme perder. Se infiere de lo que persigue en la escena. La relación entre personajes muestra qué papel cumple cada uno (aliado, opositor, apoyo) y cómo cambia el vínculo a lo largo de la obra.",
   "La evolución es el cambio del personaje entre el inicio y el final: de la desconfianza a la confianza, del orgullo a la humildad. Para afirmar que cambió, compara dos momentos con una evidencia de cada uno. Si no hay un cambio visible, se dice que el personaje es estático. Evita rótulos como «es malo» o «es bueno»: explica con evidencias qué hace, por qué lo hace y cómo cambia."],
  [("caracterización", "descripción de un personaje apoyada en evidencias"), ("motivación", "razón por la que un personaje actúa"), ("relación entre personajes", "vínculo entre ellos y papel que cumple cada uno"), ("evolución", "cambio de un personaje entre el inicio y el final"), ("estático", "que no cambia a lo largo de la obra"), ("aparte", "palabras que un personaje dirige al público o a sí mismo sin que los demás las oigan")],
  [("Caracterizar con varias vías", f"Escena de ejemplo: {EB} Caracteriza a Clara con tres vías y explica su evolución.",
    ["Lo que dice: «Con los jóvenes no se puede» muestra un prejuicio y dureza.", "Lo que se dice de ella: Tomás cuenta que ella dijo «acá nadie viene con problemas». Cómo reacciona: «se detiene» y guarda silencio al conocer el motivo.", "Evolución: pasa de la dureza a la flexibilidad al aceptar cambiar el horario."],
    "Clara es exigente y prejuiciosa al comienzo (lo que dice y lo que se dice de ella) y se vuelve flexible al final (reacciona deteniéndose y cambia el horario)"),
   ("Motivación y relación", f"Con la misma escena, {EB} ¿Cuál es la motivación de Tomás y qué relación tiene con Clara?",
    ["Tomás cambió el turno por su mamá enferma: lo que quiere es cuidarla sin perder el trabajo.", "No avisó por temor: «usted dijo que acá nadie viene con problemas».", "La relación es de jefa y empleado, con dependencia y miedo al comienzo, y de mayor confianza al final."],
    "Motivación: cuidar a su madre sin perder el empleo. Relación: de jefa y empleado con miedo a una de confianza")],
  [("Resumir a un personaje con un rótulo («es mala» o «es buena»).", "Un rótulo no es evidencia y no explica por qué actúa así.", "Reemplázalo por lo que dice, hace y cómo reacciona, con citas."),
   ("Caracterizar solo con lo que el personaje dice de sí mismo.", "Un personaje puede ocultar o contradecir lo que siente.", "Contrasta sus palabras con sus acciones, reacciones y lo que otros dicen de él.")],
  ([E("¿Qué vías permiten conocer a un personaje? A) lo que dice, lo que se dice de él, lo que hace, cómo reacciona y lo que piensa B) solo lo que dice, porque es lo único que está escrito en el texto", "A) lo que dice, lo que se dice de él, lo que hace, cómo reacciona y lo que piensa", "Cada vía aporta una evidencia distinta y se cruzan entre sí."),
    E("«Lo que se dice de un personaje» corresponde a… A) lo que otros personajes opinan sobre él B) lo que el propio personaje dice de sí mismo en un monólogo", "A) lo que otros personajes opinan sobre él", "Es la opinión de otros, que puede coincidir o no con sus acciones."),
    E("¿Qué es la motivación de un personaje? A) la razón por la que actúa B) el lugar donde ocurre la escena", "A) la razón por la que actúa", "Explica qué quiere o necesita y qué teme perder.")],
   [E("Escena de ejemplo: «(Una biblioteca de barrio. ÁNGELA ordena libros; su sobrino BRUNO, de quince años, entra de mala gana.) ÁNGELA.—Llegas tarde. BRUNO.—Mi mamá dijo que viniera.» ¿Qué vía de caracterización muestra «Llegas tarde»? A) lo que dice Ángela, con un tono brusco B) lo que otro personaje dice de Ángela en la escena", "A) lo que dice Ángela, con un tono brusco", "Son palabras de la propia Ángela, no de otro personaje."),
    E("Clasifica con D (lo que dice), S (lo que se dice de él) o H (lo que hace): 1) ÁNGELA.—«Llegas tarde.» 2) VECINA.—«Ángela es la más seria de la cuadra.» 3) «(Le pasa una caja a Bruno.)» Escribe las tres letras en orden.", "D, S, H", "La primera son palabras de Ángela; la segunda, la opinión de una vecina; la tercera, una acción."),
    E("¿Qué es la evolución de un personaje? A) el cambio que muestra entre el inicio y el final de la obra B) la cantidad de veces que habla y el tiempo que está en el escenario", "A) el cambio que muestra entre el inicio y el final de la obra", "Se comprueba comparando dos momentos con evidencias.")],
   [E("Al inicio, Bruno dice: «Mi mamá dijo que viniera». Al final, guarda un libro en su mochila y dice: «Vuelvo mañana, tía». ¿Qué evolución muestra? A) de la desgana a un interés por volver B) de la alegría a un aburrimiento profundo", "A) de la desgana a un interés por volver", "La primera frase muestra que va por obligación; la última, que quiere regresar."),
    E("Escena de ejemplo: «(Cancha de barrio. MATÍAS corre tras la pelota; su hermana CATA lo mira desde la reja.) CATA.—Te dije que hoy me tocaba la cancha. MATÍAS.—(Sin detenerse.) Mañana te la presto. CATA.—(Mira a otro lado.) Mañana el equipo ya no me va a esperar.» ¿Cuál es la motivación de Cata? A) conservar su lugar en el equipo, que no la esperará B) ganarle un partido a su hermano para demostrarle algo", "A) conservar su lugar en el equipo, que no la esperará", "Lo dice ella misma: teme perder su puesto si no juega hoy."),
    E("En esa escena, Matías no se detiene cuando Cata le recuerda que hoy le toca la cancha. ¿Qué relación se ve entre los hermanos? A) Matías pasa por encima del turno de Cata y ella se siente desplazada B) los dos juegan juntos en armonía y se turnan la cancha sin problemas", "A) Matías pasa por encima del turno de Cata y ella se siente desplazada", "Él sigue jugando y ella mira a otro lado, lo que muestra su molestia.")],
   [E("Un personaje dice «A mí no me importa nada». La acotación siguiente indica: «(Aparta la mirada y aprieta el sobre.)». ¿Qué sugiere la acotación? A) que sus palabras ocultan lo que realmente siente B) que dice toda la verdad y no oculta ningún sentimiento", "A) que sus palabras ocultan lo que realmente siente", "Su gesto contradice lo que dice, y eso es una evidencia sobre su estado interior."),
    E("Un estudiante escribe: «Pedro es malo porque grita». En la escena, Pedro grita «¡Otra vez sin las tablas!» a un compañero y después, a solas, deja sus propias tablas sobre la mesa de ese compañero. ¿Qué corrección merece? A) usar varias vías: su acción final contradice el rótulo, y su grito puede deberse a la presión por terminar B) mantener el rótulo «malo», porque gritar a un compañero es una prueba suficiente de su carácter", "A) usar varias vías: su acción final contradice el rótulo, y su grito puede deberse a la presión por terminar", "Una sola vía no basta; las acciones muestran un matiz que el rótulo ignora.")],
   [E("Acto 1: MARCELA, supervisora, corrige a su asistente RODRIGO frente a todos: «Esto está mal, otra vez». Acto 3: MARCELA le entrega un informe y le dice: «Revísalo tú antes de enviarlo. Confío en tu criterio». ¿Cómo evoluciona la relación entre ambos? A) de la corrección pública a la confianza B) de la amistad a la rivalidad abierta", "A) de la corrección pública a la confianza", "La primera frase muestra una corrección dura; la segunda, que ella le delega una tarea importante."),
    E("En la escena de la biblioteca, Ángela dice al comienzo «Entonces haz algo útil» y, cuando Bruno reconoce el libro de su padre, la acotación dice «(Suaviza la voz.)». Tres caracterizaciones de Ángela: 1) «Es seria.» 2) «Es brusca al comienzo y se suaviza cuando Bruno reconoce el libro.» 3) «Es mala persona.» ¿Cuál es más sólida? Escribe el número.", "2", "Es la única que compara dos momentos y se apoya en lo que dice y en una acotación.")]),
   [E("Para el programa de la obra del liceo debes escribir la ficha del personaje Julia con estas evidencias: dice «No necesito ayuda» cuando le ofrecen un asiento; carga sola las cajas hasta el final; su hermano comenta «Julia nunca pide nada»; la acotación dice «(Se sienta, agotada, cuando cree que nadie la mira.)». ¿Qué ficha es más sólida? A) Julia es orgullosa e independiente, pero está agotada: lo muestran sus palabras, sus acciones y su reacción cuando cree que nadie la ve B) Julia es perezosa y poco colaboradora, porque se sienta a descansar apenas cree que nadie la está mirando", "A) Julia es orgullosa e independiente, pero está agotada: lo muestran sus palabras, sus acciones y su reacción cuando cree que nadie la ve", "Cruza las cuatro vías; la otra ficha usa una sola acotación y la interpreta mal.")],
  [E("¿Qué tipo de evidencia es lo que un personaje hace en escena? A) una acción, que se cruza con sus palabras B) una opinión de otro personaje sobre su carácter", "A) una acción, que se cruza con sus palabras", "Lo que hace es una vía de caracterización distinta de lo que dice."),
   E("Si un personaje al comienzo desconfía y al final confía, ¿qué muestra? A) una evolución B) que es estático", "A) una evolución", "El cambio entre dos momentos es la evolución."),
   E("¿Por qué conviene evitar rótulos como «es malo»? A) porque no son evidencia y no explican por qué actúa así B) porque son demasiado cortos y cualquier lector los puede ignorar", "A) porque no son evidencia y no explican por qué actúa así", "La caracterización exige citas y razones.")],
  ("Lee esta escena de ejemplo: «(Un taller de bicicletas. DON HERNÁN pule una pieza; su aprendiz LENA entra con una bicicleta desarmada.) HERNÁN.—Eso lo arreglaste mal ayer. LENA.—(Deja la bicicleta con cuidado.) Lo sé. Vine a empezar de nuevo. HERNÁN.—(Sin levantar la vista.) Los que empiezan de nuevo suelen hacerlo mejor. (Le acerca un trapo.) Ponte a trabajar.» Escribe: 1) dos vías de caracterización de Lena con cita, 2) su motivación, 3) cómo muestra Hernán, con una acotación, su relación con ella.",
   "1) Lo que dice: «Lo sé. Vine a empezar de nuevo» (reconoce el error). Lo que hace: «deja la bicicleta con cuidado». 2) Quiere corregir su error y aprender bien el oficio. 3) La acotación «(Le acerca un trapo.)» muestra que Hernán la acepta y la apoya, aunque no la mire.",
   ["usa dos vías con cita", "formula la motivación", "relaciona una acotación con el vínculo entre personajes"], ["tres respuestas numeradas"], ["usar rótulos sin cita", "inventar rasgos que la escena no muestra"],
   "Comprueba que cada cita esté en la escena y que la motivación explique lo que Lena hace."),
  "Observa a una persona de una serie o película y anota una cosa que dice y una que hace y que se contradigan.",
  "Escribe una escena corta de ocho líneas donde un personaje diga una cosa y haga otra, con una acotación que lo muestre.")

# ------------------------------------------------------------------ OA 05 · clase 3
EC = "«(Sala en penumbra. Una lámpara parpadea; se oye un reloj. INÉS, de pie junto a la ventana; MARTÍN, sentado, con un sobre cerrado en las manos.) MARTÍN.—¿Y si no lo abrimos? INÉS.—(Sin volverse.) La lluvia lleva tres días. MARTÍN.—Ábrelo tú. INÉS.—(Un trueno lejano.) Tienes las manos temblando.»"
EH = "«(Cocina pequeña, tarde de invierno. Una olla humea y la radio suena baja. LUCÍA pela papas; su abuelo ARTURO se calienta las manos junto a la estufa.) ARTURO.—Hace años que no cocinábamos juntos. LUCÍA.—(Sonríe.) Hace años que no me contabas lo del tranvía. ARTURO.—Pues siéntate, que es largo.»"
EI = "«(Pasillo de un liceo, de noche. Un zumbido eléctrico constante. VERÓNICA camina de un extremo al otro; ELÍAS mira el piso. Entre los dos, una puerta cerrada: la sala del consejo.) VERÓNICA.—¿Cuánto falta? ELÍAS.—No sé. VERÓNICA.—¿Y si...? ELÍAS.—No. (Pausa larga.)»"
EJ = "«(Un faro abandonado al amanecer. Se oye el viento y, cada cierto tiempo, un golpe metálico. GASPAR sube la escalera con una linterna.) GASPAR.—(Para sí.) Nadie vive aquí. (Se detiene.) Entonces, ¿quién enciende la lámpara?»"

L(OA5, 3,
  "Aprenderé a analizar cómo se construye la atmósfera de una obra dramática a través de los diálogos, los monólogos, las acciones y las acotaciones.",
  ["Reconozco acotaciones, diálogos y monólogos.", "Caracterizo a un personaje con evidencias."],
  ["La atmósfera de una obra es la impresión o el ambiente emocional que envuelve la acción: misterio, tensión, calidez, melancolía, angustia. No se afirma sin más: se construye con recursos del texto. Los diálogos aportan ritmo y tono (frases cortas y cortadas crean tensión; frases largas y suaves, calma). Los monólogos muestran el interior de un personaje. Las acciones y las pausas dejan ver lo que no se dice. Las acotaciones describen el lugar, la luz, los sonidos y los gestos.",
   "Para analizar la atmósfera, identifica la sensación dominante y busca de dónde sale: ¿hay frases cortas?, ¿silencios?, ¿sonidos como un reloj o una lluvia?, ¿luz tenue o fuerte?, ¿objetos que inquietan? Varios recursos se refuerzan entre sí. La atmósfera se explica con al menos dos recursos y sus citas: «la atmósfera es de tensión porque los diálogos son cortos y las acotaciones señalan un sobre cerrado y un trueno».",
   "Un recurso no produce siempre el mismo efecto: la lluvia puede dar melancolía en una obra y alivio en otra. Por eso se analiza en el contexto de la escena. También se observa cómo cambia la atmósfera a lo largo de ella (por ejemplo, de la calma a la inquietud) y qué momento provoca el cambio. No atribuyas la atmósfera a un solo recurso sin evidencia del texto."],
  [("atmósfera", "ambiente emocional que envuelve la acción de una obra"), ("tono", "manera de decir algo que revela una emoción"), ("pausa", "silencio indicado en el texto, que también comunica"), ("tensión", "sensación de que algo importante está por ocurrir"), ("recurso", "elemento del texto que aporta a un efecto")],
  [("Analizar una atmósfera", f"Escena de ejemplo: {EC} ¿Qué atmósfera predomina y cómo se construye?",
    ["La sensación es de tensión e inquietud.", "Las acotaciones aportan penumbra, una lámpara que parpadea, un reloj y un trueno; el sobre cerrado es un objeto que inquieta.", "Los diálogos son cortos y evitan decir lo temido («¿Y si no lo abrimos?»)."],
    "Tensión e inquietud, construida con acotaciones (penumbra, lámpara, reloj, trueno), un sobre sin abrir y diálogos breves"),
   ("Cambiar la atmósfera con las acotaciones", f"Con los mismos diálogos de la escena, {EC} cambia la primera acotación por «(Sala luminosa. Afuera, niños juegan. INÉS está de pie junto a la ventana; MARTÍN, sentado, con un sobre en las manos.)». ¿Qué ocurre con la atmósfera?",
    ["Quito la penumbra, el reloj y el parpadeo.", "Agrego luz y juegos afuera: la sala se siente segura.", "El diálogo mantiene la duda, pero la atmósfera pasa de la inquietud a una intriga más ligera."],
    "La atmósfera se aligera: sin penumbra ni sonidos inquietantes, la duda del diálogo pierde parte de su tensión")],
  [("Decir «la atmósfera es de misterio» sin ninguna cita.", "Sin evidencia es una opinión.", "Cita al menos dos recursos del texto que la construyan."),
   ("Pensar que un recurso siempre produce el mismo efecto (la lluvia = tristeza).", "El efecto depende de la escena.", "Explica qué hace el recurso en este texto concreto.")],
  ([E("¿Qué es la atmósfera de una obra? A) el ambiente emocional que envuelve la acción B) el nombre del lugar y de la época en que ocurre", "A) el ambiente emocional que envuelve la acción", "Se refiere a la impresión o sensación dominante, no al lugar."),
    E("¿Cuál es una acotación? A) «(Se oye un golpe metálico.)» B) GASPAR.—«Nadie vive aquí.»", "A) «(Se oye un golpe metálico.)»", "Está entre paréntesis y describe un sonido; la otra línea la dice un personaje."),
    E("Los diálogos formados por frases cortas y cortadas suelen crear… A) tensión B) calma", "A) tensión", "El ritmo entrecortado transmite urgencia o dificultad para hablar.")],
   [E(f"Escena de ejemplo: {EH} ¿Qué atmósfera predomina? A) cálida e íntima B) misteriosa C) angustiante", "A) cálida e íntima", "Una olla humeante, una radio baja y un abuelo que va a contar una historia crean cercanía."),
    E(f"En esa escena, {EH} ¿qué acotaciones aportan calidez? A) una olla que humea, la radio baja y el abuelo calentándose las manos B) los nombres de los personajes y las indicaciones de entrada y salida", "A) una olla que humea, la radio baja y el abuelo calentándose las manos", "Describen un ambiente acogedor; los nombres no crean ambiente."),
    E(f"En la escena del faro, {EJ} ¿qué hace la pregunta final de Gaspar? A) deja una incógnita que aumenta el misterio B) resuelve el misterio y explica quién enciende la lámpara", "A) deja una incógnita que aumenta el misterio", "Si nadie vive allí, que la lámpara se encienda plantea un enigma.")],
   [E(f"Escena de ejemplo: {EI} ¿Qué recursos construyen la tensión? A) el zumbido eléctrico, la puerta cerrada, las frases cortas y la pausa larga B) solo el nombre de Verónica y la hora en que ocurre la escena", "A) el zumbido eléctrico, la puerta cerrada, las frases cortas y la pausa larga", "Sonido, espacio, ritmo del diálogo y silencio se refuerzan entre sí."),
    E("En un pasillo, ELÍAS responde «No» cuando VERÓNICA dice «¿Y si...?». ¿Qué muestra la frase interrumpida? A) que lo temido queda sin decir, lo que aumenta la angustia B) que discuten por dinero y por quién tiene la razón", "A) que lo temido queda sin decir, lo que aumenta la angustia", "Lo no dicho genera inquietud; nada del texto habla de dinero."),
    E("Si la escena del pasillo (zumbido eléctrico, puerta cerrada, frases cortas) terminara con la acotación «(Se abre la puerta y salen todos sonriendo.)». ¿Qué efecto tendría sobre la atmósfera? A) la tensión pasaría a alivio B) la tensión aumentaría", "A) la tensión pasaría a alivio", "Una acotación final con sonrisas cierra la espera con una nota positiva.")],
   [E(f"Un estudiante dice que en la escena del faro, {EJ} la atmósfera de misterio se debe «solo al viento». ¿Qué falla? A) la atribuye a un solo recurso y hay otros: el golpe metálico, el faro abandonado y la pregunta final B) el viento no aparece en el texto y por eso no puede crear ningún ambiente", "A) la atribuye a un solo recurso y hay otros: el golpe metálico, el faro abandonado y la pregunta final", "La atmósfera se explica con varios recursos que se refuerzan."),
    E("En una escena llueve y el aire es de melancolía; en otra, llueve y los personajes celebran el fin de la sequía. ¿Qué muestra esto? A) que un mismo recurso puede producir efectos distintos según el contexto B) que la lluvia siempre produce melancolía, sin importar la escena", "A) que un mismo recurso puede producir efectos distintos según el contexto", "El efecto de un recurso se analiza dentro de cada escena.")],
   [E("Escena de ejemplo: «(Plaza de un pueblo, mediodía luminoso. Se oyen risas y una banda.) PEDRO.—Qué día precioso. (La banda se detiene; silencio. Todos miran hacia la puerta de la iglesia.) PEDRO.—(Bajando la voz.) ¿Y ahora qué pasa?» ¿Qué cambio de atmósfera ocurre y qué lo provoca? A) pasa de la alegría a la inquietud cuando la banda se detiene y llega el silencio B) pasa del miedo a la alegría cuando la banda deja de tocar", "A) pasa de la alegría a la inquietud cuando la banda se detiene y llega el silencio", "La acotación inicial es luminosa y festiva; el silencio y la mirada colectiva cambian el ambiente."),
    E("Quieres que una escena de cocina cálida (olla humeante, radio baja, un abuelo y su nieta que conversan en confianza) se vuelva inquietante cambiando solo las acotaciones. ¿Qué cambio es más eficaz? A) luz fría y parpadeante, la radio con interferencias y el abuelo mirando la puerta B) agregar más papas sobre la mesa y un mantel de colores", "A) luz fría y parpadeante, la radio con interferencias y el abuelo mirando la puerta", "Cambia luz, sonido y gesto para sugerir amenaza; añadir papas no altera el ambiente.")]),
   [E("Escribirás las acotaciones de una escena en que dos hermanos esperan una llamada importante y quieres una atmósfera de tensión. ¿Qué propuesta funciona mejor? A) «(Una sola lámpara. El teléfono está mudo sobre la mesa. Se oye un reloj. Ninguno se mira.)» B) «(Habitación llena de luz. Se oye música alegre. Los dos hermanos conversan y se ríen.)»", "A) «(Una sola lámpara. El teléfono está mudo sobre la mesa. Se oye un reloj. Ninguno se mira.)»", "Luz escasa, teléfono mudo, reloj y evasión de miradas se refuerzan para crear tensión.")],
  [E("¿Con cuántos recursos conviene explicar una atmósfera? A) con al menos dos, citados del texto B) con uno solo, el más llamativo", "A) con al menos dos, citados del texto", "Varios recursos se refuerzan y dan mayor respaldo."),
   E("Una pausa larga indicada en el texto… A) también comunica, porque muestra lo que no se dice B) no aporta nada, porque el silencio no se puede analizar", "A) también comunica, porque muestra lo que no se dice", "El silencio es un recurso que se analiza como cualquier otro."),
   E("¿Un mismo recurso produce siempre el mismo efecto? A) no: depende del contexto de la escena B) sí, siempre, porque cada recurso tiene un significado fijo", "A) no: depende del contexto de la escena", "Se analiza dentro de cada obra.")],
  ("Lee esta escena de ejemplo: «(Una casa de campo al anochecer. Un perro ladra a lo lejos. ROSARIO cierra las ventanas una por una; su hijo DAVID prepara la mesa para tres personas.) ROSARIO.—Son las ocho. DAVID.—Ya sé. ROSARIO.—(Mirando la tercera silla.) Él siempre llega antes. DAVID.—(Pone el tercer plato.) Entonces llegará.» Escribe: 1) la atmósfera que percibes, 2) tres recursos con cita que la construyen, 3) cómo cambiarías dos acotaciones para lograr una atmósfera de espera alegre.",
   "1) Una espera tensa y algo triste. 2) La acotación del perro que ladra a lo lejos y las ventanas cerradas; los diálogos cortos («Son las ocho». «Ya sé.»); el tercer plato puesto para alguien que no llega. 3) Cambiaría «Un perro ladra a lo lejos» por «Suena música suave en la radio» y «cierra las ventanas» por «abre la ventana para ver la calle».",
   ["identifica una atmósfera adecuada", "cita tres recursos distintos", "propone cambios coherentes en dos acotaciones"], ["tres respuestas numeradas"], ["explicar la atmósfera con un solo recurso", "citar frases que no están en la escena"],
   "Marca cada cita en la escena y comprueba que cambiaste acotaciones y no los diálogos."),
  "Escucha en tu casa un fragmento de una radionovela o de una serie sin imagen y anota qué sonidos construyen el ambiente.",
  "Escribe dos acotaciones iniciales para una misma escena: una que cree misterio y otra que cree alegría.")

# ------------------------------------------------------------------ OA 05 · clase 4
ED = "«(Una estación pequeña. LUCÍA, con una maleta. TOMÁS, su abuelo, sostiene un termo.) TOMÁS.—Llévate esto. LUCÍA.—(Lo recibe.) Te voy a llamar. TOMÁS.—Está bien.»"

L(OA5, 4,
  "Aprenderé a describir cómo los elementos de la puesta en escena (iluminación, sonido, vestuario, escenografía y actuación) aportan a la comprensión de la obra y a contrastar dos puestas en escena del mismo texto.",
  ["Distingo el texto dramático de su representación.", "Explico cómo se construye una atmósfera."],
  ["La puesta en escena es la forma en que un equipo (dirección, actores y diseño) convierte el texto en una obra viva. Incluye la iluminación (cómo se usa la luz: cálida, fría, tenue, intensa), el sonido (música, ruidos, silencios), el vestuario (la ropa y sus colores), la escenografía (el espacio y los objetos del escenario) y la actuación (voz, gestos, movimiento y distancia entre los actores). Cada elemento cambia lo que sentimos y entendemos de un personaje o de un conflicto.",
   "Dos puestas en escena de un mismo texto pueden interpretarlo de modo distinto. Para contrastarlas se describe cada elemento con precisión (qué luz, qué sonido) y se explica qué efecto produce y qué interpretación apoya. Una escena de despedida con luz cálida y música suave resalta el cariño; la misma escena con luz fría y silencio resalta la distancia. Ninguna es «la correcta»: se evalúa cuál se apoya mejor en el texto.",
   "No hay que confundir el texto con la representación: el texto trae diálogos y acotaciones, y la puesta en escena decide cómo cumplirlos. Al analizar una función vista, un video o una descripción, se comenta primero lo que se ve y se oye, y después su efecto. Y no se atribuye todo a un solo elemento sin evidencia escénica."],
  [("puesta en escena", "forma en que un equipo convierte el texto en obra con actores, luz, sonido y espacio"), ("iluminación", "uso de la luz en el escenario"), ("sonido", "música, ruidos y silencios de la obra"), ("vestuario", "ropa y colores que usan los personajes"), ("escenografía", "espacio y objetos del escenario"), ("actuación", "voz, gestos y movimiento de los actores")],
  [("Describir y evaluar el efecto", f"Texto de ejemplo: {ED} Puesta A: luz cálida y baja de atardecer, guitarra suave, el abuelo con chaleco de colores terrosos, los actores muy cerca y Lucía abraza el termo. Puesta B: luz blanca y fría desde arriba, silencio con un zumbido, ropa gris, los actores en extremos opuestos del escenario sin mirarse. ¿Qué resalta cada una?",
    ["Describo cada elemento: luz, sonido, vestuario, distancia entre los actores.", "En A, la luz cálida, la guitarra y la cercanía resaltan el cariño.", "En B, la luz fría, el silencio y la distancia resaltan la frialdad y la separación."],
    "A resalta el cariño y la cercanía; B, la distancia y la frialdad"),
   ("Evaluar con el texto", f"Con el mismo texto, {ED} ¿cuál puesta (A: cálida y cercana; B: fría y distante) se apoya mejor en lo escrito?",
    ["Busco en el texto un gesto de cuidado: «Llévate esto» y el termo.", "La puesta A hace visible ese cuidado; la B podría apoyarse en las frases breves («Está bien»), pero contradice el objeto cuidado.", "Ambas son posibles, pero A explica más líneas del texto."],
    "Ambas son posibles; A se apoya mejor porque explica el termo y «Llévate esto»")],
  [("Decir que una puesta en escena es «la correcta» y las otras están mal.", "Cada puesta interpreta el texto; lo que se evalúa es qué apoyo tiene en él.", "Compara qué líneas del texto explica cada una."),
   ("Atribuir el sentido de la obra a un solo elemento («es de miedo por la música»).", "Los elementos de la puesta en escena se refuerzan entre sí y con el texto.", "Describe varios elementos y relaciónalos con el texto.")],
  ([E("¿Qué es la escenografía? A) el espacio y los objetos del escenario B) la ropa y los colores de los actores", "A) el espacio y los objetos del escenario", "El vestuario es la ropa; la escenografía incluye el espacio y los objetos."),
    E("¿Qué incluye la iluminación? A) cómo se usa la luz en el escenario B) la música y los ruidos de la función", "A) cómo se usa la luz en el escenario", "La música y los ruidos son parte del sonido."),
    E("¿Qué es la puesta en escena? A) la forma de convertir el texto en una obra con actores, luz, sonido y espacio B) el texto escrito de la obra con sus diálogos y acotaciones", "A) la forma de convertir el texto en una obra con actores, luz, sonido y espacio", "El texto es el punto de partida; la puesta en escena es la representación.")],
   [E("Un actor habla en voz baja y muy cerca del otro. ¿A qué elemento de la puesta en escena corresponde? A) la actuación B) el vestuario", "A) la actuación", "La voz y la distancia entre actores son decisiones de actuación."),
    E("En una función se oye lluvia constante y una música sola, sin diálogos, durante una escena. ¿A qué elemento corresponde? A) el sonido B) la escenografía", "A) el sonido", "La lluvia y la música son recursos sonoros."),
    E("El escenario tiene una mesa larga vacía y una sola silla. ¿A qué elemento corresponde? A) la escenografía B) la iluminación", "A) la escenografía", "Son objetos y espacio del escenario.")],
   [E("Texto de ejemplo: «(Un comedor. LAURA y su hermano IVÁN, con una silla vacía entre ambos.) LAURA.—Mamá se demora. IVÁN.—(Mira el reloj.) Como siempre.» Puesta A: luz cálida, mesa con flores, música suave. Puesta B: luz tenue azulada, mesa sin mantel, un reloj que suena fuerte. ¿Cuál resalta mejor la espera tensa y cansada? A) la B, por la luz tenue azulada y el reloj que suena fuerte B) la A, por las flores en la mesa y la música suave", "A) la B, por la luz tenue azulada y el reloj que suena fuerte", "Subraya el paso del tiempo y el cansancio de «como siempre»; las flores y la luz cálida suavizan la escena."),
    E("En una puesta, la reina viste de negro con bordes rojos y el criado, de gris claro. ¿Qué puede comunicar ese contraste? A) diferencias de poder o de carácter entre los personajes B) que la obra transcurre de día y en un lugar cerrado", "A) diferencias de poder o de carácter entre los personajes", "El vestuario y sus colores caracterizan a los personajes y su rol."),
    E("Una acotación dice «(Cae la noche.)». Un equipo baja gradualmente la luz; otro cambia un fondo pintado. ¿Qué muestra esto? A) que una misma acotación puede cumplirse con recursos distintos B) que el texto no sirve para montar la obra sin cambiar las acotaciones", "A) que una misma acotación puede cumplirse con recursos distintos", "La puesta en escena decide cómo realizar lo que el texto indica.")],
   [E("Un estudiante escribe: «La obra trata del miedo porque había música de terror». El texto de la escena solo muestra a dos amigos que conversan sobre un examen. ¿Qué falla? A) atribuye el sentido a un solo elemento sin apoyo en el texto B) la música no es parte de la puesta en escena sino del texto", "A) atribuye el sentido a un solo elemento sin apoyo en el texto", "La música de la función no cambia lo que dice el texto; hay que relacionar los elementos con él."),
    E("Dos reseñas. Reseña 1: «La puesta con luz fría fue la correcta». Reseña 2: «Cada puesta interpreta el texto de forma distinta; hay que evaluar cuál se apoya mejor en él». ¿Cuál es más precisa? A) la reseña 2 B) la reseña 1", "A) la reseña 2", "Reconoce que hay más de una interpretación posible y propone un criterio.")],
   [E("Texto de ejemplo: «(Un living. ROMINA recibe una caja de su padre; él la mira con expectación.) PADRE.—¿No la abres? ROMINA.—(Sonríe sin mostrar los dientes.) Después. Gracias.» Puesta A: Romina abre la caja de inmediato y grita de alegría. Puesta B: Romina sostiene la caja sin abrirla, con la mirada baja y la voz casi inaudible, bajo luz tenue. La interpretación es «Romina oculta su emoción». ¿Qué puesta la apoya? A) la B, porque coincide con «sonríe sin mostrar los dientes» y «después» B) la A, porque es más alegre y Romina muestra que agradece el regalo", "A) la B, porque coincide con «sonríe sin mostrar los dientes» y «después»", "La contención de la actuación de B dialoga con las palabras y la acotación; en A abre la caja en seguida."),
    E("Se describe una puesta: «luz desde arriba, vestuario blanco, mesa y dos sillas, actores que hablan sin mirarse». De los cinco elementos de la clase, ¿cuál NO se menciona? A) el sonido B) la actuación C) el vestuario", "A) el sonido", "Aparecen iluminación (luz desde arriba), vestuario, escenografía (mesa y sillas) y actuación; falta el sonido.")]),
   [E("Viste la obra del liceo. En la escena de la discusión, los actores gritaban bajo una luz roja intensa. Una compañera dice que eso muestra la rabia. ¿Qué dos elementos de la puesta en escena se mencionan? A) la actuación y la iluminación B) el vestuario y la escenografía", "A) la actuación y la iluminación", "Gritar es actuación (voz); la luz roja intensa es iluminación.")],
  [E("¿Qué se hace primero al analizar una función vista? A) describir lo que se ve y se oye B) opinar si fue buena o mala", "A) describir lo que se ve y se oye", "La descripción precisa permite explicar después el efecto."),
   E("Dos puestas del mismo texto con luces y sonidos opuestos… A) pueden interpretarlo de modo distinto B) siempre son idénticas porque el texto es el mismo", "A) pueden interpretarlo de modo distinto", "La puesta en escena es una interpretación del texto."),
   E("¿Qué debe hacer una puesta en escena respecto de las acotaciones del texto? A) decidir cómo cumplirlas con recursos escénicos B) ignorarlas siempre y dejar que los actores improvisen", "A) decidir cómo cumplirlas con recursos escénicos", "Las acotaciones se realizan de formas posibles que decide el equipo.")],
  ("Lee este texto de ejemplo: «(Un patio escolar, hora de salida. MAIA espera sola; llega su amiga ELENA.) ELENA.—Me cambiaron de curso. MAIA.—(Después de un silencio.) Ya.» Puesta 1: luz cálida del atardecer, sonido de niños jugando lejos, las dos actrices a un metro de distancia, voz suave. Puesta 2: luz gris, silencio total, una reja entre las actrices, voz seca. Escribe: 1) qué elementos de cada puesta se describen, 2) qué interpreta cada una, 3) cuál se apoya mejor en el texto y por qué, 4) una tercera puesta tuya con tres elementos.",
   "1) En la puesta 1: iluminación, sonido y actuación (distancia y voz suave). En la 2: iluminación, sonido, escenografía (reja) y actuación (voz seca). 2) La 1 muestra tristeza con cariño; la 2, frialdad y separación. 3) La 2 se apoya en el «Ya» seco y en el silencio previo, aunque la 1 también es posible si el silencio es de pena. 4) Mi puesta: luz tenue de tarde, un banco entre las dos y actrices que se miran sin hablar al final.",
   ["describe elementos concretos", "explica el efecto de cada puesta", "justifica con una línea del texto", "propone una puesta con tres elementos"], ["cuatro respuestas numeradas"], ["valorar sin describir", "atribuir todo a un solo elemento"],
   "Comprueba que cada elemento mencionado esté en la descripción y que tu justificación cite una línea del texto."),
  "Si puedes, mira un fragmento de una obra de teatro, grabado o en vivo, y anota qué luz, sonido y vestuario viste.",
  "Describe dos puestas en escena distintas de una escena de tu elección, con tres elementos cada una.")

# ------------------------------------------------------------------ OA 05 · clase 5
EF = "«(Trastienda de un almacén, en un pueblo de una época pasada imaginaria. DON FÉLIX, el dueño, revisa un libro de cuentas; su hija ISABEL entra con unos papeles.) FÉLIX.—Las muchachas no necesitan libros: necesitan un buen casamiento. ISABEL.—(Con firmeza.) Padre, llevo las cuentas del almacén desde hace dos años. Usted mismo lo dijo. FÉLIX.—Una cosa es ayudar y otra pretender.»"
EL = "«(Sala de profesores de un liceo imaginario, hace muchos años. El INSPECTOR revisa una lista; el joven PROFESOR NUEVO observa.) INSPECTOR.—Los alumnos del campo llegan siempre tarde y sin ganas. No pierda tiempo con ellos. PROFESOR NUEVO.—(Mira la lista.) Pero aquí dice que Andrés viaja dos horas cada mañana. INSPECTOR.—Excusas.»"
EM = "«(Una cocina. NICO, de dieciséis años, usa el teléfono; su tía OLGA lo mira.) OLGA.—Los jóvenes de hoy no saben conversar. NICO.—(Levanta la vista.) Estoy preguntándole al abuelo cómo se hacía el pan de campo; me manda la receta por mensajes.»"

L(OA5, 5,
  "Aprenderé a situar un texto dramático en su contexto: identificar creencias, prejuicios y estereotipos presentes en el relato, explicarlos desde la visión de mundo de la época en que fue escrito y conectarlos con el mundo actual.",
  ["Caracterizo personajes con evidencias.", "Distingo lo que dice un personaje de lo que defiende la obra."],
  ["Toda obra nace en un contexto: una época, una sociedad y una visión de mundo, es decir, el conjunto de ideas y valores con que se ve la realidad. Por eso los personajes pueden expresar creencias (ideas que se dan por ciertas), prejuicios (juicios sobre alguien o algo sin conocerlo bien) y estereotipos (imágenes simplificadas de un grupo, como «los jóvenes son irresponsables»). Detectarlos no significa aprobarlos: la obra puede mostrarlos para criticarlos, cuestionarlos o reflejar su época.",
   "Para analizarlos se pregunta: ¿qué creencia o prejuicio expresa el personaje?, ¿en qué palabras o actos se nota?, ¿cómo lo trata la obra: lo apoya, lo cuestiona o lo muestra sin comentario?, ¿qué visión de mundo de esa época explica que un personaje piense así? Se evita juzgar a la época con ligereza: primero se explica y después se compara con el presente.",
   "La conexión con el mundo actual consiste en preguntarse si ese prejuicio o estereotipo sigue existiendo hoy, con qué formas y qué cambió. Por ejemplo, hoy la educación es un derecho de todas las personas, pero todavía pueden oírse ideas sobre qué estudios o trabajos serían «para hombres» o «para mujeres». Al comentar estos temas, usa casos de la obra y no de personas reales, y apóyate en citas."],
  [("contexto", "época, sociedad y circunstancias en que nace una obra"), ("visión de mundo", "conjunto de ideas y valores con que una sociedad ve la realidad"), ("creencia", "idea que se da por cierta"), ("prejuicio", "juicio sobre alguien o algo sin conocerlo bien"), ("estereotipo", "imagen simplificada de un grupo de personas")],
  [("Detectar y explicar un prejuicio", f"Escena de ejemplo: {EF} ¿Qué prejuicio aparece y cómo lo trata la obra?",
    ["Don Félix afirma que «las muchachas no necesitan libros: necesitan un buen casamiento»: es un estereotipo sobre qué deben hacer las mujeres.", "Isabel lo cuestiona con un hecho: lleva las cuentas del almacén desde hace dos años.", "La obra lo muestra en una sociedad imaginaria con roles rígidos y lo cuestiona mediante la respuesta de Isabel."],
    "Estereotipo: las mujeres no necesitan estudiar, solo casarse. La obra lo cuestiona con el argumento y el hecho de Isabel"),
   ("Conectar con el mundo actual", f"Con la misma escena, {EF} ¿qué conexión tiene con el presente?",
    ["Hoy la educación es un derecho de todas las personas, a diferencia de la sociedad imaginaria de la escena.", "Pero siguen apareciendo ideas sobre qué estudios o trabajos serían «para hombres» o «para mujeres».", "La escena permite preguntarse qué estereotipos de este tipo persisten."],
    "El derecho a estudiar hoy es de todas las personas, pero aún hay estereotipos sobre estudios y trabajos «para hombres» o «para mujeres»")],
  [("Pensar que, si un personaje expresa un prejuicio, la obra lo defiende.", "La obra puede mostrarlo para cuestionarlo o reflejar su época.", "Fíjate en cómo lo tratan los otros personajes, las acciones y las acotaciones."),
   ("Juzgar a la época sin explicarla («la gente de antes era tonta»).", "El juicio sin explicación no analiza la visión de mundo.", "Explica qué ideas de la época sostenían ese prejuicio y luego compáralas con hoy.")],
  ([E("¿Qué es un prejuicio? A) un juicio sobre alguien o algo sin conocerlo bien B) una opinión basada en datos comprobados y en la experiencia", "A) un juicio sobre alguien o algo sin conocerlo bien", "El prejuicio se forma antes de conocer; una opinión con datos es otra cosa."),
    E("¿Qué es la visión de mundo de una época? A) el conjunto de ideas y valores con que una sociedad ve la realidad B) el paisaje que se ve desde el escenario y que cambia con la época", "A) el conjunto de ideas y valores con que una sociedad ve la realidad", "Explica por qué los personajes piensan como piensan."),
    E("La frase «todos los jóvenes son irresponsables» es… A) un estereotipo B) un hecho comprobado", "A) un estereotipo", "Simplifica a un grupo entero con una sola imagen.")],
   [E(f"Escena de ejemplo: {EM} ¿Qué estereotipo expresa Olga? A) que los jóvenes no saben conversar B) que los abuelos no usan mensajes", "A) que los jóvenes no saben conversar", "Lo dice con una frase general sobre «los jóvenes de hoy»."),
    E(f"En esa escena, {EM} ¿cómo trata la obra ese estereotipo? A) lo cuestiona mostrando a Nico conversando con su abuelo por mensajes B) lo confirma con la actitud de Nico, que mira el teléfono sin hablar", "A) lo cuestiona mostrando a Nico conversando con su abuelo por mensajes", "La acción de Nico contradice la generalización de su tía."),
    E("Cuando se detecta un prejuicio en una obra, ¿qué significa? A) que la obra lo muestra y hay que ver si lo apoya o lo cuestiona B) que el autor siempre lo comparte y lo defiende en toda la obra", "A) que la obra lo muestra y hay que ver si lo apoya o lo cuestiona", "Mostrar no es lo mismo que aprobar.")],
   [E(f"Escena de ejemplo: {EL} ¿Qué dato de la escena cuestiona el estereotipo del inspector? A) que Andrés viaja dos horas cada mañana B) que el inspector revisa una lista", "A) que Andrés viaja dos horas cada mañana", "El dato muestra que el atraso tiene una causa y no es falta de ganas."),
    E("En una escena de ejemplo, un inspector asegura que los alumnos del campo llegan siempre tarde y sin ganas. ¿Qué visión de mundo puede explicar ese prejuicio? A) juzgar a las personas por su origen sin conocer sus circunstancias B) valorar el esfuerzo de cada estudiante, sin importar de dónde viene", "A) juzgar a las personas por su origen sin conocer sus circunstancias", "Generaliza sobre un grupo sin mirar los casos."),
    E("Hoy todavía se oye la frase «los de ese barrio son todos iguales». ¿Qué relación tiene con el inspector de la escena que dice que los alumnos del campo llegan siempre tarde y sin ganas? A) es un estereotipo parecido, porque juzga a un grupo por su origen B) no tiene relación alguna, porque hoy ya no se oyen estereotipos", "A) es un estereotipo parecido, porque juzga a un grupo por su origen", "Ambas frases simplifican a un grupo de personas.")],
   [E("Un estudiante dice: «La obra defiende que los forasteros traen problemas, porque un personaje lo dice». En la escena, DOÑA MIRTA afirma que los forasteros solo traen problemas y, después, un médico recién llegado atiende con éxito a su nieto y ella baja la mirada. ¿Qué falla? A) confunde lo que dice un personaje con lo que defiende la obra; la acción final contradice a Mirta B) nada: la obra defiende ese prejuicio porque lo dice un personaje en el texto", "A) confunde lo que dice un personaje con lo que defiende la obra; la acción final contradice a Mirta", "La acción y la acotación final cuestionan el prejuicio de la anciana."),
    E("Un lector sostiene: «Como la obra es de otra época, no se puede comparar con el presente». ¿Qué respuesta es más sólida? A) se puede explicar el prejuicio desde su época y luego compararlo con el presente B) no se puede comparar nunca, porque las épocas son demasiado distintas", "A) se puede explicar el prejuicio desde su época y luego compararlo con el presente", "Entender el contexto permite una comparación fundamentada.")],
   [E("Escena de ejemplo: «(Estación de tren de un pueblo imaginario. DON BERNARDO, comerciante, habla con el joven LEO, que carga una guitarra.) BERNARDO.—Los músicos no tienen oficio. LEO.—Pago mi arriendo tocando en los matrimonios. BERNARDO.—(Riendo.) Eso no es trabajo, es diversión.» ¿Qué idea de la visión de mundo de Bernardo se ve? A) que solo se considera trabajo lo que parece pesado o conocido B) que el arte vale siempre más que el comercio y debe ser el único oficio", "A) que solo se considera trabajo lo que parece pesado o conocido", "Leo explica que vive de tocar y Bernardo igual lo descalifica."),
    E("Una persona de una obra antigua dice «una mujer no debe viajar sola» y una persona de hoy dice «los hombres no deben llorar». ¿Qué tienen en común ambas frases? A) son estereotipos que limitan lo que alguien «debe» hacer según su género B) ninguna es un estereotipo, porque ambas se refieren a una sola persona", "A) son estereotipos que limitan lo que alguien «debe» hacer según su género", "Ambas simplifican y condicionan conductas según el género.")]),
   [E(f"Después de ver la escena del inspector y los alumnos del campo ({EL}) debes preparar una pregunta para el foro del curso. ¿Cuál es la más pertinente? A) ¿qué prejuicio aparece, cómo lo cuestiona la obra y dónde lo vemos hoy? B) ¿cuánto cuesta la entrada y a qué hora comienza la función?", "A) ¿qué prejuicio aparece, cómo lo cuestiona la obra y dónde lo vemos hoy?", "Combina prejuicio, tratamiento de la obra y conexión con el presente.")],
  [E("¿Qué hace la obra con un prejuicio que un personaje expresa? A) puede apoyarlo, cuestionarlo o mostrarlo sin comentario B) siempre lo aprueba, porque lo dice un personaje", "A) puede apoyarlo, cuestionarlo o mostrarlo sin comentario", "Hay que mirar las acciones y los otros personajes."),
   E("¿Qué es un estereotipo? A) una imagen simplificada de un grupo de personas B) un dato comprobado sobre una persona concreta", "A) una imagen simplificada de un grupo de personas", "Reduce a un grupo a un solo rasgo."),
   E("Para conectar una obra con el presente, ¿qué conviene preguntarse? A) si ese prejuicio sigue existiendo hoy, con qué formas y qué cambió B) cuántos actores había y cuánto duró la función en total", "A) si ese prejuicio sigue existiendo hoy, con qué formas y qué cambió", "La conexión con el mundo actual compara continuidades y cambios.")],
  ("Lee esta escena de ejemplo: «(Una sastrería de una época pasada imaginaria. DON RAÚL, el sastre, entrega un traje a ADELA, la nueva aprendiz, de quince años.) RAÚL.—Las jovencitas se distraen. Dos semanas y se van. ADELA.—(Midiendo la manga.) Llevo ocho días y ya aprendí a cortar sin desperdicio. RAÚL.—(Mirando el corte.) Suerte de principiante.» Escribe: 1) el prejuicio que expresa Raúl, 2) una cita de la escena que lo cuestiona, 3) cómo trata la obra ese prejuicio, 4) una conexión con el presente en una oración, sin hablar de personas reales.",
   "1) Que las jóvenes no tienen constancia para un oficio. 2) «Llevo ocho días y ya aprendí a cortar sin desperdicio». 3) La obra lo cuestiona: Adela muestra con un hecho lo contrario, y Raúl solo responde con «Suerte de principiante». 4) Hoy todavía se oyen frases como «los jóvenes no aguantan un trabajo», que juzgan a todo un grupo por su edad.",
   ["nombra el prejuicio", "cita una evidencia que lo cuestiona", "explica el tratamiento de la obra", "hace una conexión actual sin personas reales"], ["cuatro respuestas numeradas"], ["afirmar que la obra defiende lo que dice un personaje", "juzgar a la época sin explicar"],
   "Verifica que la cita esté en la escena y que la conexión actual no apunte a personas reales."),
  "Anota un estereotipo que hayas oído en una serie o en la vida cotidiana y escribe un dato que lo contradiga, sin nombrar personas.",
  "Escribe tres líneas de una escena donde un personaje exprese un prejuicio y otro lo cuestione con un hecho.")

# ------------------------------------------------------------------ OA 05 · clase 6
EP = "«(Un banquete. El CAPITÁN BRAVO, de uniforme lleno de medallas, habla fuerte ante los invitados.) BRAVO.—Yo solo derroté a cincuenta. (Su criado TOMÁS le rellena la copa y murmura al público.) TOMÁS.—Y esta mañana se asustó de un gato.»"
EQ = "«(Un jardín al atardecer. JULIETA y su abuela PEPA, sentadas junto a un rosal.) PEPA.—Cada rosa dura un día. JULIETA.—Entonces no la cortes. PEPA.—Al contrario, niña: huélela hoy, que mañana ya no está.»"
ER = "«(Una tienda. Un reloj de pared detenido a las cinco. DON ANSELMO cuenta monedas; su sobrino BENJAMÍN barre.) ANSELMO.—Una moneda más y quedo tranquilo. BENJAMÍN.—Lleva treinta años diciendo eso, tío. ANSELMO.—(Mira el reloj parado.) Ese reloj no se arregla: costaría dinero. BENJAMÍN.—Pero la vida pasa igual, tío, aunque el reloj no la marque.»"

L(OA5, 6,
  "Aprenderé a reconocer personajes tipo, símbolos y tópicos literarios en una obra dramática y a formular una lectura propia de una escena, apoyada en evidencias.",
  ["Analizo conflicto, personajes y atmósfera con evidencias.", "Distingo creencias y prejuicios en una escena."],
  ["Un personaje tipo es una figura que representa un rasgo, un oficio o un rol social que se repite en muchas obras, con pocos matices: el avaro, el fanfarrón, el criado astuto, la madre protectora. Reconocerlo ayuda a ver qué muestra o qué critica la obra, aunque un buen autor puede darle matices. Un símbolo teatral es un objeto, un espacio o un gesto que representa una idea: un reloj detenido puede representar una vida detenida. Un tópico literario es un tema o motivo que se repite a lo largo del tiempo, como el paso del tiempo o aprovechar el presente (en latín, carpe diem).",
   "Una lectura propia de una obra dramática es una afirmación sobre su sentido, sostenida con evidencias de varias vías: el conflicto y el problema humano, la evolución de un personaje, la atmósfera, algún elemento de la puesta en escena y, si corresponde, un personaje tipo, un símbolo o un tópico. Se formula con verbos prudentes («la obra sugiere que…») y se apoya en citas de diálogos o acotaciones.",
   "Antes de escribir, elige una idea central y busca dos o tres evidencias que de verdad la prueben; descarta las que no sirven. Explica cada una con tus palabras y cierra relacionando la idea con el problema humano de la obra. Evita resumir la trama o enumerar elementos sin conectarlos: una lectura no es una lista."],
  [("personaje tipo", "figura que representa un rasgo o un rol social repetido en muchas obras"), ("símbolo teatral", "objeto, espacio o gesto que representa una idea"), ("tópico literario", "tema o motivo que se repite a lo largo del tiempo"), ("carpe diem", "expresión latina que significa «aprovecha el día»"), ("lectura propia", "interpretación de la obra defendida con evidencias")],
  [("Reconocer personaje tipo, símbolo y tópico", f"Escena de ejemplo: {ER} ¿Qué personaje tipo, símbolo y tópico aparecen?",
    ["Don Anselmo cuenta monedas y no arregla el reloj para no gastar: es un avaro.", "El reloj detenido representa una vida detenida por la avaricia: es un símbolo.", "La frase «la vida pasa igual» remite al tópico del paso del tiempo."],
    "Personaje tipo: el avaro. Símbolo: el reloj detenido. Tópico: el paso del tiempo"),
   ("Formular una lectura propia", f"Con la misma escena, {ER} escribe una lectura propia de dos oraciones.",
    ["Elijo una idea central: la avaricia no detiene el tiempo.", "Evidencia 1: Anselmo no repara el reloj porque «costaría dinero». Evidencia 2: Benjamín dice que «la vida pasa igual».", "Cierro con el problema humano: el apego al dinero que impide vivir el presente."],
    "La escena sugiere que la avaricia no detiene el tiempo, porque Anselmo deja el reloj parado para ahorrar mientras Benjamín le recuerda que «la vida pasa igual»; el problema humano es el apego al dinero que impide vivir el presente")],
  [("Pensar que un personaje tipo es un personaje sin importancia.", "Un personaje tipo puede ser central: solo representa un rasgo o rol que se repite.", "Pregunta qué rasgo representa y qué muestra la obra con él."),
   ("Escribir una lista de elementos («hay un reloj, un tío y un sobrino») y llamarla lectura.", "Una lista no interpreta ni conecta las evidencias.", "Elige una idea central y conecta cada elemento con ella.")],
  ([E("¿Qué es un personaje tipo? A) una figura que representa un rasgo o un rol social repetido en muchas obras B) un personaje que aparece una sola vez y casi no habla", "A) una figura que representa un rasgo o un rol social repetido en muchas obras", "Es una figura reconocible, como el avaro o el fanfarrón."),
    E("¿Qué es un símbolo teatral? A) un objeto, espacio o gesto que representa una idea B) cualquier objeto que aparece en el escenario", "A) un objeto, espacio o gesto que representa una idea", "No todo objeto es símbolo: lo es el que representa una idea."),
    E("¿Qué es un tópico literario? A) un tema o motivo que se repite a lo largo del tiempo B) una frase inventada por un solo autor para su obra", "A) un tema o motivo que se repite a lo largo del tiempo", "El paso del tiempo es un ejemplo de tópico.")],
   [E(f"Escena de ejemplo: {EP} ¿Qué personaje tipo representa el Capitán? A) el fanfarrón B) el avaro", "A) el fanfarrón", "Presume de hazañas exageradas y la escena muestra que no son verdad."),
    E("En la escena del banquete, el criado Tomás sabe la verdad sobre el Capitán y se la murmura al público con ingenio. ¿Qué lo hace un «criado astuto»? A) que dice la verdad con ingenio desde su lugar subordinado B) que obedece sin pensar y nunca dice lo que sabe", "A) que dice la verdad con ingenio desde su lugar subordinado", "Evidencia la mentira del amo sin enfrentarlo abiertamente."),
    E(f"Escena de ejemplo: {EQ} ¿Qué tópico aparece? A) el paso del tiempo y aprovechar el presente B) la búsqueda del poder y de la riqueza", "A) el paso del tiempo y aprovechar el presente", "La rosa que dura un día y «huélela hoy» remiten a eso.")],
   [E(f"En la escena del rosal, {EQ} ¿qué objeto funciona como símbolo? A) la rosa que dura un día, que representa lo breve del tiempo B) el jardín, que representa la riqueza de la familia", "A) la rosa que dura un día, que representa lo breve del tiempo", "El texto relaciona la rosa con el tiempo que pasa; la riqueza no aparece."),
    E(f"Sobre la escena del banquete ({EP}), ¿cuál es una lectura propia y no un resumen? A) «La escena sugiere que presumir hazañas falsas deja en ridículo, pues Tomás revela que el Capitán se asustó de un gato» B) «La escena tiene un capitán con muchas medallas y un criado que rellena la copa» C) «El Capitán es malo y mentiroso, y por eso el criado se burla de él en voz baja»", "A) «La escena sugiere que presumir hazañas falsas deja en ridículo, pues Tomás revela que el Capitán se asustó de un gato»", "Formula una idea y la prueba con una cita; las otras solo enumeran o rotulan."),
    E("En la escena del rosal, ¿qué línea prueba mejor el tópico de aprovechar el presente (carpe diem)? A) «huélela hoy, que mañana ya no está» B) «Cada rosa dura un día», porque nombra la flor", "A) «huélela hoy, que mañana ya no está»", "Invita a disfrutar hoy; la otra línea solo habla de lo breve de la rosa.")],
   [E("Una estudiante dice: «Un personaje tipo es un personaje sin importancia». ¿Qué falla? A) puede ser central: solo significa que representa un rasgo o rol repetido B) tiene razón, porque aparece poco y no cambia durante la obra", "A) puede ser central: solo significa que representa un rasgo o rol repetido", "Que sea un tipo no lo hace secundario."),
    E("Un estudiante escribe como lectura: «En la obra aparecen un reloj, un capitán y una rosa». ¿Qué falla? A) enumera elementos sin conectarlos con una idea central B) menciona demasiados elementos y la lectura queda muy larga", "A) enumera elementos sin conectarlos con una idea central", "Una lectura propia afirma un sentido y conecta los elementos con él.")],
   [E(f"Dos lecturas de la escena del banquete ({EP}). Lectura 1: «Se critica la vanidad de quienes presumen». Lectura 2: «Se critica a los criados». ¿Cuál tiene respaldo? A) la 1, porque Tomás revela la verdad del Capitán B) la 2, porque Tomás es un criado que murmura al público", "A) la 1, porque Tomás revela la verdad del Capitán", "El texto muestra al Capitán en ridículo; Tomás aparece como quien dice la verdad."),
    E("Escena de ejemplo: «(Una plaza con un reloj de sol roto. DOÑA CLOTILDE, anciana, y su nieto RAMÓN.) CLOTILDE.—Cuando era niña, aquí la sombra marcaba las horas. RAMÓN.—Ahora miramos el celular. CLOTILDE.—(Toca la piedra.) Pero la sombra sigue pasando.» ¿Qué símbolo y qué tópico se combinan? A) el reloj de sol roto, símbolo del tiempo que sigue pasando, y el tópico del paso del tiempo B) el celular, símbolo de la riqueza de la familia, y el tópico del amor imposible entre abuela y nieto", "A) el reloj de sol roto, símbolo del tiempo que sigue pasando, y el tópico del paso del tiempo", "La frase «la sombra sigue pasando» conecta el objeto con el tópico.")]),
   [E("Para el programa de un festival debes escribir una frase de lectura propia de una obra con un personaje vanidoso que cubre con una tela un espejo roto y dice «me veo perfecto». ¿Cuál frase es una lectura y no un resumen? A) «La obra sugiere que la vanidad lleva a negar los defectos propios, como el personaje que cubre el espejo roto y se declara perfecto» B) «La obra cuenta que un personaje vanidoso cubre con una tela un espejo roto y dice que se ve perfecto, sin interpretar nada»", "A) «La obra sugiere que la vanidad lleva a negar los defectos propios, como el personaje que cubre el espejo roto y se declara perfecto»", "Interpreta un sentido y lo apoya con una acción; la otra solo cuenta lo que ocurre.")],
  [E("¿Qué debe tener una lectura propia de una obra dramática? A) una idea central apoyada en citas de diálogos o acotaciones B) un resumen de toda la trama y una opinión personal sobre ella", "A) una idea central apoyada en citas de diálogos o acotaciones", "Interpretar es distinto de contar la trama."),
   E("Si un reloj detenido representa una vida detenida, ¿qué es? A) un símbolo teatral B) un personaje tipo", "A) un símbolo teatral", "Es un objeto que representa una idea."),
   E("¿Qué tópico representa la expresión «aprovecha el día»? A) carpe diem B) la búsqueda del poder y de la riqueza", "A) carpe diem", "Es la expresión latina que se explicó en la clase.")],
  ("Lee esta escena de ejemplo: «(Una peluquería vacía. DON SERGIO, el peluquero, mira la puerta. Sobre el espejo, un calendario con las hojas sin arrancar.) SERGIO.—(Hablando solo.) Mañana vuelven los clientes. VECINA.—(Asomada a la puerta.) Don Sergio, hace tres años que dice lo mismo. SERGIO.—(Sin volverse, ajustando una silla.) Esta vez es cierto.» Escribe una lectura propia de tres o cuatro oraciones que incluya: una idea central con verbo prudente, un símbolo, dos citas y el problema humano.",
   "La escena sugiere que Sergio se niega a aceptar un cambio y se sostiene con una esperanza repetida. El calendario con las hojas sin arrancar simboliza un tiempo detenido. La vecina lo muestra al decir «hace tres años que dice lo mismo», y Sergio insiste con «esta vez es cierto» mientras ajusta una silla. El problema humano es la dificultad de aceptar que algo ya cambió.",
   ["formula una idea central con verbo prudente", "interpreta un símbolo", "cita dos evidencias", "nombra el problema humano"], ["párrafo de tres o cuatro oraciones"], ["resumir la escena", "enumerar elementos sin conectarlos"],
   "Subraya la idea central, el símbolo, las dos citas y el problema humano; comprueba que estén los cuatro."),
  "Piensa en un personaje de una serie o película que sea un tipo reconocible y anota qué rasgo representa.",
  "Escribe una escena de cinco líneas con un personaje tipo y un símbolo, e indica qué idea representa el símbolo.")

# ------------------------------------------------------------------ OA 05 · clase 7
EV = "«(Un tribunal imaginario hecho de cajas de cartón. EL LOBO, con corbata, ante la JUEZA, una abuela con anteojos.) JUEZA.—Se le acusa de haberse comido a una niña de capa roja. LOBO.—(Indignado.) Yo solo pregunté el camino. Fue ella quien cortó por el bosque.»"
EW = "«(Una sala de clases de una época pasada imaginaria. El MAESTRO lee en voz alta una lista de apellidos. Al final, dice:) MAESTRO.—Los que no figuran aquí pueden irse. (Un niño, SIMÓN, se queda sentado junto a la ventana. La luz se vuelve gris.)»"
EX = "«(Un pasillo de museo. Un VIGILANTE le pide a LORENA que no toque un cuadro; ella retira la mano.) VIGILANTE.—(Con voz suave.) Mire, pero no toque. LORENA.—(Sin dejar de mirar el cuadro.) ¿Y si el cuadro quiere que lo toquen? VIGILANTE.—(Sonríe.) Entonces tendría que pedirlo.»"

L(OA5, 7,
  "Aprenderé a reconocer relaciones intertextuales en una obra dramática, a revisar un análisis con una lista de criterios y a transferir lo aprendido a una escena nueva.",
  ["Analizo conflicto, personajes, atmósfera y puesta en escena.", "Formulo una lectura propia con evidencias."],
  ["Las relaciones intertextuales aparecen cuando una obra retoma, cita, parodia o reescribe otro texto: un cuento tradicional, un mito, otra obra. Una parodia es una imitación que exagera o cambia algo para hacer reír o criticar. Se analiza qué se retoma (personajes, conflicto, frases), qué se cambia (época, punto de vista, final) y qué efecto tiene ese cambio. Retomar un cuento tradicional, como el de Caperucita Roja, permite jugar con lo que el público ya conoce y ofrecer una mirada nueva, por ejemplo, contar la historia desde el lobo.",
   "Revisar un análisis dramático es volver sobre él con una lista: 1) ¿identifica el conflicto y el problema humano?, 2) ¿caracteriza a los personajes con varias vías y evidencias?, 3) ¿explica cómo se construye la atmósfera con más de un recurso?, 4) ¿distingue texto y puesta en escena?, 5) ¿considera creencias, prejuicios o estereotipos y su contexto?, 6) ¿señala personajes tipo, símbolos, tópicos y relaciones intertextuales cuando son pertinentes? Se corrigen las fallas: afirmaciones sin cita, rótulos sin evidencia, un efecto atribuido a un solo recurso.",
   "Transferir es aplicar esta manera de leer a una escena nueva, sin repetir los ejemplos. Un lector autónomo elige qué puntos de la lista ayudan más en cada caso y los desarrolla con evidencias. Al cerrar, compara lo que habías entendido al principio con lo que entiendes ahora: ese cambio es parte del aprendizaje."],
  [("intertextualidad", "relación de un texto con otros textos"), ("parodia", "imitación que exagera o cambia algo para hacer reír o criticar"), ("reescritura", "versión nueva de una historia ya conocida"), ("lista de revisión", "conjunto de preguntas para comprobar un análisis"), ("transferir", "aplicar lo aprendido a una situación nueva")],
  [("Analizar una relación intertextual", f"Escena de ejemplo: {EV} ¿Qué se retoma, qué se cambia y qué efecto tiene?",
    ["Se retoma el cuento tradicional de Caperucita Roja: el lobo y la niña de capa roja.", "Se cambia el formato (un juicio con cajas de cartón) y el punto de vista: ahora habla el lobo.", "El efecto es humor y una pregunta: ¿quién cuenta la historia?"],
    "Retoma a Caperucita y al lobo; cambia a un juicio y al punto de vista del lobo; produce humor y cuestiona quién cuenta la historia"),
   ("Revisar un análisis flojo", f"Con la misma escena, {EV} un análisis dice: «La obra es graciosa porque sale un lobo». Revísalo con la lista de la clase.",
    ["Punto 6: no señala qué texto se retoma ni qué cambia.", "Punto 1: no menciona el conflicto (acusación y defensa).", "Reescribo con cita y efecto."],
    "Versión mejorada: «La escena parodia el cuento de Caperucita Roja: cambia el bosque por un tribunal y da la palabra al lobo, que dice “yo solo pregunté el camino”; así cuestiona quién cuenta la historia»")],
  [("Decir «es una parodia» sin explicar qué se retoma y qué se cambia.", "La etiqueta sola no analiza la relación.", "Nombra el texto retomado, el cambio y su efecto."),
   ("Agregar muchas citas que no se relacionan con la idea central.", "Las citas deben probar la idea; más citas no mejoran un análisis.", "Elige solo las citas que sostienen tu idea y explícalas.")],
  ([E("¿Qué es una parodia? A) una imitación que exagera o cambia algo para hacer reír o criticar B) una copia exacta de otro texto, sin cambios ni exageración", "A) una imitación que exagera o cambia algo para hacer reír o criticar", "Retoma algo conocido, pero lo transforma."),
    E("Al analizar una relación intertextual, ¿qué se compara? A) qué se retoma, qué se cambia y qué efecto produce B) cuántas páginas y cuántos personajes tiene cada texto", "A) qué se retoma, qué se cambia y qué efecto produce", "Esos tres pasos permiten explicar la relación."),
    E("Transferir lo aprendido significa… A) aplicarlo a una escena nueva B) repetir los ejemplos de la clase", "A) aplicarlo a una escena nueva", "El procedimiento se usa con otro texto, no con los mismos ejemplos.")],
   [E("Escena de ejemplo: «(Una cocina de palacio. CENICIENTA, con delantal, discute con el HADA MADRINA, que consulta una libreta.) HADA.—Tu carroza se convierte en calabaza a medianoche. CENICIENTA.—(Cruzada de brazos.) ¿Y por qué no a las doce y cuarto? Ese horario es injusto.» ¿Qué se retoma del cuento tradicional? A) los personajes y la regla de la medianoche B) solo los personajes, no las reglas del cuento", "A) los personajes y la regla de la medianoche", "Aparecen Cenicienta, el hada madrina y la carroza que se convierte en calabaza a medianoche."),
    E("En esa escena (Cenicienta discute con el hada madrina, que consulta una libreta, porque la carroza se convierte en calabaza a medianoche), ¿qué se cambia respecto del cuento tradicional? A) la magia se trata como un trámite que se discute con una libreta B) el final, que ahora es triste y deja a Cenicienta sola", "A) la magia se trata como un trámite que se discute con una libreta", "El hada consulta una libreta y Cenicienta reclama el horario: la magia pasa a ser un reglamento."),
    E("¿Qué efecto tiene en esa escena el reclamo «¿Y por qué no a las doce y cuarto?»? A) humor, porque trata la magia como un reglamento B) terror, porque amenaza a un personaje con la medianoche", "A) humor, porque trata la magia como un reglamento", "Convierte lo mágico en algo cotidiano y exagera para hacer reír.")],
   [E("Un análisis dice solamente: «La escena es una parodia». Según la lista de la clase, ¿qué le falta? A) citar qué texto se retoma y qué se cambia B) agregar más adjetivos y una opinión sobre el cuento", "A) citar qué texto se retoma y qué se cambia", "El punto 6 exige señalar la relación intertextual con evidencias."),
    E("Un análisis afirma que la atmósfera de una escena es de miedo «por la música». ¿Qué punto de la lista no cumple? A) el 3: no explica la atmósfera con más de un recurso B) el 1: no menciona el conflicto ni el problema humano", "A) el 3: no explica la atmósfera con más de un recurso", "Atribuye el efecto a un solo recurso."),
    E("Una frase de un análisis dice: «Lo que se dice de Clara (“acá nadie viene con problemas”) y lo que hace (se detiene) muestran su cambio». ¿Qué punto de la lista cumple? A) el 2: caracteriza a un personaje con varias vías y evidencias B) el 4: distingue entre el texto y la puesta en escena", "A) el 2: caracteriza a un personaje con varias vías y evidencias", "Cruza lo que se dice de ella con lo que hace, con citas.")],
   [E("Una compañera dice: «Parodiar un cuento es faltarle el respeto, así que la escena no tiene valor». ¿Qué respuesta es más sólida? A) la parodia usa lo conocido para ofrecer una mirada nueva o crítica; se evalúa qué cambia y qué efecto tiene B) tiene razón: un cuento tradicional no se debe cambiar ni reescribir de ninguna forma", "A) la parodia usa lo conocido para ofrecer una mirada nueva o crítica; se evalúa qué cambia y qué efecto tiene", "Las relaciones intertextuales se analizan por lo que retoman y transforman."),
    E("Un estudiante revisó su análisis y agregó cinco citas, pero ninguna se relaciona con su idea central. ¿Mejoró? A) no: las citas deben probar la idea; más citas no bastan B) sí, porque tiene más citas y eso hace más sólido el análisis", "A) no: las citas deben probar la idea; más citas no bastan", "La calidad de la evidencia importa más que la cantidad.")],
   [E(f"Escena de ejemplo: {EW} ¿Qué análisis integra mejor atmósfera, contexto y evidencias? A) «La escena sugiere que excluir sin escuchar deja a Simón sin lugar; la luz gris refuerza una atmósfera de abandono y el maestro muestra un prejuicio de la época sobre quién estudia» B) «La escena habla de un maestro que lee una lista de apellidos y de un niño que se queda sentado junto a la ventana» C) «Es una obra de terror, porque la luz se vuelve gris y esa acotación crea miedo en todo el texto»", "A) «La escena sugiere que excluir sin escuchar deja a Simón sin lugar; la luz gris refuerza una atmósfera de abandono y el maestro muestra un prejuicio de la época sobre quién estudia»", "Combina conflicto, atmósfera con acotación y contexto con citas; las otras no interpretan o atribuyen un efecto a un solo recurso."),
    E("Te entregan un monólogo breve con luz tenue y sonido de lluvia en las acotaciones. ¿Qué puntos de la lista pesan más? A) la atmósfera construida con acotaciones y el problema humano interior B) las relaciones intertextuales, porque siempre existen en toda obra de teatro", "A) la atmósfera construida con acotaciones y el problema humano interior", "Un monólogo con luz y sonido pide mirar su ambiente y lo que expresa el personaje; la intertextualidad solo se analiza cuando es pertinente.")]),
   [E("Tu curso discute una puesta que reescribe «Cenicienta» desde el punto de vista de la madrastra. Para el foro anotas tres preguntas. ¿Cuál corresponde a intertextualidad? A) ¿qué retoma del cuento tradicional y qué cambia al contarlo desde la madrastra? B) ¿cuánto duró la función y cuántos actores participaron?", "A) ¿qué retoma del cuento tradicional y qué cambia al contarlo desde la madrastra?", "Pregunta por lo retomado y lo transformado en la relación con otro texto.")],
  [E("¿Qué se corrige al revisar un análisis dramático? A) afirmaciones sin cita, rótulos sin evidencia y efectos atribuidos a un solo recurso B) solo la ortografía, la puntuación y el orden de los párrafos", "A) afirmaciones sin cita, rótulos sin evidencia y efectos atribuidos a un solo recurso", "Son las fallas de contenido que la lista ayuda a detectar."),
   E("¿Cuándo se analiza una relación intertextual? A) cuando es pertinente, es decir, cuando la escena realmente retoma otro texto B) siempre, aunque no haya relación, para que el análisis sea completo", "A) cuando es pertinente, es decir, cuando la escena realmente retoma otro texto", "No se inventan relaciones: se muestran con evidencias."),
   E("Al cerrar un análisis, ¿qué es valioso comparar? A) lo que entendías al principio con lo que entiendes ahora B) tu análisis con el de otra persona para copiarlo", "A) lo que entendías al principio con lo que entiendes ahora", "Reconocer el cambio de comprensión es parte del aprendizaje.")],
  (f"Lee esta escena de ejemplo y este análisis flojo. Escena: {EX} Análisis flojo: «La escena es graciosa. Hay una chica y un vigilante.» Con la lista de la clase, escribe: 1) dos fallas del análisis flojo, 2) un análisis mejorado de tres oraciones con conflicto, problema humano y una cita de acotación, 3) una oración sobre qué cambió en tu comprensión de la escena.",
   "1) No identifica el conflicto ni el problema humano, y no cita ninguna línea. 2) El conflicto es la tensión entre la norma del museo (no tocar) y la curiosidad de Lorena. El problema humano es el choque entre las reglas y el deseo de acercarse a lo que nos conmueve. La acotación «(Con voz suave.)» muestra que el vigilante hace cumplir la norma con amabilidad. 3) Al principio solo vi una escena graciosa; ahora veo que dice algo sobre normas y curiosidad.",
   ["detecta dos fallas reales", "identifica conflicto y problema humano", "cita una acotación", "reflexiona sobre su comprensión"], ["tres respuestas numeradas"], ["repetir el análisis flojo con otras palabras", "mejorar sin citar la escena"],
   "Aplica los seis puntos de la lista a tu análisis mejorado y marca cuáles cumple."),
  "Revisa un análisis que hayas escrito antes con la lista de la clase y anota un cambio concreto.",
  "Escribe una escena de seis líneas que parodie un cuento tradicional y explica qué retomas, qué cambias y qué efecto buscas.")
